        popup:slider("Speed",   0.2, 3,   World.FX.Rain.Speed,   2, function(v) World.FX.Rain.Speed = v end)
        popup:slider("Streak",  1, 40,    World.FX.Rain.Streak,  1, function(v) World.FX.Rain.Streak = v end)
        popup:slider("Wind",   -12, 12,   World.FX.Rain.Wind,    1, function(v) World.FX.Rain.Wind = v end)
        popup:slider("Reach",   0.25, 6,  World.FX.Rain.Reach,   2, function(v) World.FX.Rain.Reach = v end)
    end)
    -- v0.9.0
    local sakRow = configCheckbox(fx2, "Sakura", World.FX.Sakura.Enabled,
        function(v) World.FX.Sakura.Enabled = v end)
    attachSingleSwatch(sakRow.row, World.FX.Sakura.Color, function(c) World.FX.Sakura.Color = c end)
    rightClickSettings(sakRow.row, "Sakura", function(popup)
        popup:slider("Density", 10, 600, World.FX.Sakura.Density, 0, function(v) World.FX.Sakura.Density = math.floor(v) end)
        popup:slider("Speed",   0.2, 3,  World.FX.Sakura.Speed,   2, function(v) World.FX.Sakura.Speed = v end)
        popup:slider("Size",    0.1, 3,  World.FX.Sakura.Size,    2, function(v) World.FX.Sakura.Size = v end)
        popup:slider("Sway",    0, 80,   World.FX.Sakura.Sway,    0, function(v) World.FX.Sakura.Sway = v end)
        popup:slider("Wind",   -16, 16,  World.FX.Sakura.Wind,    1, function(v) World.FX.Sakura.Wind = v end)
        popup:slider("Spin",    0, 400,  World.FX.Sakura.Spin,    0, function(v) World.FX.Sakura.Spin = v end)
        popup:slider("Reach",   0.25, 6, World.FX.Sakura.Reach,   2, function(v) World.FX.Sakura.Reach = v end)
    end)

    -- v0.6.0: RULES sub-tab. Plus button + list of rule rows (name + delete).
    -- Clicking the name opens a rename popup. Plus opens the rule-type picker.
    local rulesCard = panel(W.Rules, "Rules")
    local headerRow = new("Frame", {
        Size = UDim2.new(1, 0, 0, 24), BackgroundTransparency = 1,
        ZIndex = 33, Parent = rulesCard,
    })
    new("TextLabel", {
            Text = "Your rules apply live, and save with your config.",
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.new(0, 0, 0, 4), Size = UDim2.new(1, -34, 0, 16),
        ZIndex = 34, Parent = headerRow,
    })
    local plusBtn = new("TextButton", {
        Text = "+", FontFace = Theme.Fonts.Bold, TextSize = 16,
        AutoButtonColor = false, TextColor3 = Theme.Palette.Text,
        BackgroundColor3 = Theme.Palette.Accent, BackgroundTransparency = 0.15,
        BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 0),
        Position = UDim2.new(1, 0, 0, 0), Size = UDim2.new(0, 26, 0, 20),
        ZIndex = 34, Parent = headerRow,
    }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
    plusBtn.MouseButton1Click:Connect(function()
        if Shared.openRuleTypePicker then Shared.openRuleTypePicker() end
    end)

    local rulesList = new("Frame", {
        Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1, ZIndex = 33, Parent = rulesCard,
    }, { new("UIListLayout", { Padding = UDim.new(0, 4),
        SortOrder = Enum.SortOrder.LayoutOrder }) })
    local emptyLabel = new("TextLabel", {
            Text = "No rules yet: click + to add one.",
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Size = UDim2.new(1, 0, 0, 20), ZIndex = 34, Parent = rulesList,
    })

    local function refreshRules()
        -- v0.8.2: was `ch:IsA("Frame") and ch ~= emptyLabel`. Correct today purely
        -- by accident of class hierarchy: TextLabel does NOT inherit from Frame,
        -- so the reference check never actually did anything, and the moment
        -- emptyLabel became a Frame (an icon, a styled empty card) every refresh
        -- would have destroyed it and left the empty state permanently blank.
        -- Keep by REFERENCE, and spare UIComponents (the UIListLayout) by class,
        -- so the sweep is honest about what it is protecting and why.
        for _, ch in ipairs(rulesList:GetChildren()) do
            if ch ~= emptyLabel and not ch:IsA("UIComponent") then ch:Destroy() end
        end
        emptyLabel.Visible = (#Shared.WorldRules.List == 0)
        for i, rule in ipairs(Shared.WorldRules.List) do
            local row = new("Frame", {
                Size = UDim2.new(1, 0, 0, 26),
                BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.3,
                BorderSizePixel = 0, LayoutOrder = i, ZIndex = 34, Parent = rulesList,
            }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
            -- type badge
            new("TextLabel", {
                Text = (rule.type == "AntiAnimation" and "Anti-Anim" or "Offset"),
                FontFace = Theme.Fonts.Mono, TextSize = 10,
                TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1,
                Position = UDim2.new(0, 8, 0, 0), Size = UDim2.new(0, 64, 1, 0),
                TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 35, Parent = row,
            })
            -- name: clicking opens rename popup
            local nameBtn = new("TextButton", {
                Text = rule.name, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Body,
                TextColor3 = Theme.Palette.Text, AutoButtonColor = false,
                BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
                Position = UDim2.new(0, 76, 0, 0), Size = UDim2.new(1, -110, 1, 0),
                TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 35, Parent = row,
            })
            nameBtn.MouseButton1Click:Connect(function()
                if Shared.openTextPopup then
                    Shared.openTextPopup("rename rule", rule.name, "new name",
                        function(newName) Shared.renameRule(rule.id, newName) end)
                end
            end)
            -- delete icon
            local delBtn = new("TextButton", {
                Text = "X", FontFace = Theme.Fonts.Bold, TextSize = 14,
                AutoButtonColor = false, TextColor3 = Theme.Palette.Danger or Color3.fromRGB(220, 90, 90),
                BackgroundColor3 = Theme.Palette.Panel, BackgroundTransparency = 0.35,
                BorderSizePixel = 0,
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -6, 0.5, 0), Size = UDim2.new(0, 22, 0, 20),
                ZIndex = 35, Parent = row,
            }, { corner(4), stroke(Theme.Palette.BorderSubtle) })
            delBtn.MouseButton1Click:Connect(function() Shared.removeRule(rule.id) end)
        end
    end
    Shared._rulesListRefresh = refreshRules
    refreshRules()
end)

addTab("Character", function(root) Koffee._characterTab(root) end)

-- v0.0.96: options state (arraylist preferences) rides the config system too.
registerConfig("options", KoffeeOptions)

-- v0.11.0 CUSTOM UI COLORS. Widgets bake Theme.Palette values straight into
-- BackgroundColor3 / TextColor3 / UIStroke.Color at construction, across hundreds of
-- call sites. Tagging every one with its palette role would be a far larger and more
-- fragile change than this: instead, remember the palette currently ON SCREEN and,
-- when a role changes, sweep the two ScreenGuis swapping that exact colour for the
-- new one. The stock palette values are distinct enough for the match to be
-- unambiguous, and re-pointing Theme.Palette keeps anything built later in step.
--
-- State-driven rather than fired from the swatch callback, so a loaded config
-- repaints too. Throttled because the colour picker fires continuously while you
-- drag it, and a full GetDescendants sweep per frame would visibly stutter.
;(function()
    local ROLES = { "Accent", "Background", "Panel", "PanelElevated", "Border",
                    "Text", "TextMuted" }
    local live, lastAt = {}, 0
    for _, r in ipairs(ROLES) do live[r] = Theme.Palette[r] end

    -- v0.12.1: repaint by ROLE TAG (stamped in new()), not by value. Value matching
    -- collided as soon as two roles shared a colour: set Panel to white and every
    -- near-white label was claimed by Panel, so Text could never repaint again.
    -- Untagged instances (colour assigned after construction) get matched by value
    -- ONCE and tagged, so they're exact from then on.
    -- KUserColor marks instances whose colour is the user's DATA (swatch previews,
    -- picker chips), not chrome: repainting those desynced preview from value.
    local function paint(d, prop)
        local role = d:GetAttribute("KR" .. prop)
        if not role then
            local cur = d[prop]
            for _, r in ipairs(ROLES) do
                if cur == live[r] then role = r; d:SetAttribute("KR" .. prop, r); break end
            end
            if not role then return end
        end
        local c = KoffeeOptions.UIColors[role]
        if c and d[prop] ~= c then d[prop] = c end
    end
    local function repaint(root)
        for _, d in ipairs(root:GetDescendants()) do
            if d:GetAttribute("KUserColor") then
                -- data, not chrome: leave it alone
            elseif d:IsA("GuiObject") then
                paint(d, "BackgroundColor3")
                if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then
                    paint(d, "TextColor3")
                    if d:IsA("TextBox") then paint(d, "PlaceholderColor3") end
                end
                if d:IsA("ImageLabel") or d:IsA("ImageButton") then paint(d, "ImageColor3") end
                if d:IsA("ScrollingFrame") then paint(d, "ScrollBarImageColor3") end
            elseif d:IsA("UIStroke") then
                paint(d, "Color")
            end
        end
    end

    RunService.Heartbeat:Connect(function()
        if Koffee.dead() then return end
        local want = KoffeeOptions.UIColors
        if not want then return end
        local now = os.clock()
        if now - lastAt < 0.08 then return end
        local dirty = false
        for _, r in ipairs(ROLES) do
            if want[r] and want[r] ~= live[r] then dirty = true; break end
        end
        if not dirty then return end
        lastAt = now
        pcall(repaint, screen)
        pcall(repaint, popupScreen)
        for _, r in ipairs(ROLES) do
            if want[r] then Theme.Palette[r] = want[r]; live[r] = want[r] end
        end
        -- the arraylist embeds its detail / "on" tags as RichText colour STRINGS, so
        -- the sweep can't see them. Re-point; the label poll rebuilds them itself.
        local function rich(c)
            return string.format("rgb(%d,%d,%d)",
                math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5),
                math.floor(c.B * 255 + 0.5))
        end
        ROW.muted = rich(Theme.Palette.TextMuted)
        ROW.on    = rich(Theme.Palette.Accent)
    end)
end)()

-- OPTIONS TAB (v0.0.34)
addTab("Options", function(root)
    local card = panel(root, "Options")

    local uiPanel = panel(root, "Interface")
    local arrRow = configCheckbox(uiPanel, "Arraylist", KoffeeOptions.Arraylist, function(v)
        KoffeeOptions.Arraylist = v
        activeArray.Visible = v
    end)
    configCheckbox(uiPanel, "Top Bar", KoffeeOptions.TopBar, function(v)
        KoffeeOptions.TopBar = v
        applyTopBar()
    end)

    -- v0.26.0: the three background effects that play while the window is open.
    -- Re-applying with the live bg state makes each toggle take effect instantly.
    local bgPanel = panel(root, "Menu Background")
    configCheckbox(bgPanel, "Dim", KoffeeOptions.MenuDim, function(v)
        KoffeeOptions.MenuDim = v
        setBackgroundActive(bgActive)
    end)
    configCheckbox(bgPanel, "Blur", KoffeeOptions.MenuBlur, function(v)
        KoffeeOptions.MenuBlur = v
        setBackgroundActive(bgActive)
    end)
    configCheckbox(bgPanel, "Snow", KoffeeOptions.MenuSnow, function(v)
        KoffeeOptions.MenuSnow = v
        setBackgroundActive(bgActive)
    end)
    -- v0.48.0: animation settings. Master + speed + one flag per surface, all
    -- read live so they take effect instantly, all nil-means-on so old configs
    -- animate exactly as before. Persisted through registerConfig("options").
    local animPanel = panel(root, "Animations")
    local function animFlag(label, key)
        configCheckbox(animPanel, label, KoffeeOptions[key] ~= false, function(v)
            KoffeeOptions[key] = v
        end)
    end
    configCheckbox(animPanel, "Animations", KoffeeOptions.AnimOn ~= false, function(v)
        KoffeeOptions.AnimOn = v
    end)
    slider(animPanel, "Speed", 0.5, 2, KoffeeOptions.AnimSpeed or 1, 1, function(v)
        KoffeeOptions.AnimSpeed = v
    end)
    animFlag("Window Open", "AnimWindow")
    animFlag("Tab Switching", "AnimTabs")
    animFlag("Popups", "AnimPopups")
    animFlag("Button Press", "AnimPress")
    animFlag("Hover", "AnimHover")
    animFlag("Lists", "AnimLists")
    animFlag("Toggles", "AnimToggles")
    rightClickSettings(arrRow.row, "Arraylist", function(menu)
        -- v0.33.0: the accent line was white-only since v0.0.1: now recolourable.
        menu:swatch("Line Colour", KoffeeOptions.ArraylistLineColor or Theme.Palette.Snow, function(c)
            KoffeeOptions.ArraylistLineColor = c
            applyArrayLineColor()
        end)
        menu:toggle("Overwrite Outline", KoffeeOptions.ArraylistOutline, function(v)
            KoffeeOptions.ArraylistOutline = v
        end)
        menu:slider("Outline Size", 1, 5, KoffeeOptions.ArraylistOutlineSize, 0, function(v)
            KoffeeOptions.ArraylistOutlineSize = v
        end)
    end)

    -- v0.0.97 CUSTOM FONT: applies a user-chosen font to everything that isn't
    -- the main Koffee window (arraylist, ESP name / distance / health text, HUD
    -- stats, etc.). The dropdown lists the fonts hosted on koffee-assets (see
    -- FONTS_CATALOG); right-click the row to tune the global text size used while
    -- the custom font is on: so the pixel fonts don't render too big / small.
    -- Default off + "None": feature interface looks exactly like before.
    -- v0.4.0: expanded font catalog. "None" reverts to Theme.Fonts. The rest split
    -- into: external assets (downloaded via koffee-assets) + roblox stock families
    -- (zero-cost, resolved via rbxasset://fonts/families/*.json inside loadFeiFont).
    -- v0.9.0: shared catalog list (see Theme.FontNames) instead of a second literal.
    local fontOptions = Theme.FontNames
    -- user-dropped fonts land in the workspace as koffee_<name>.otf; surface any
    -- extra cached entries the catalog doesn't know so they're selectable too.
    local fontRow = configCheckbox(uiPanel, "Custom Font", KoffeeOptions.CustomFontOn, function(v)
        KoffeeOptions.CustomFontOn = v
        Theme.setFeiOn(v)
        if v then Theme.setFeiFont(KoffeeOptions.CustomFontName) end
    end)
    rightClickSettings(fontRow.row, "Custom Font", function(menu)
        menu:slider("Font Size", 8, 28, KoffeeOptions.CustomFontSize, 0, function(v)
            KoffeeOptions.CustomFontSize = v
            Theme.setFeiSize(v)
        end)
    end)
    dropdown(uiPanel, "Font", fontOptions, KoffeeOptions.CustomFontName, function(v)
        KoffeeOptions.CustomFontName = v
        Theme.setFeiFont(v)
    end)
    -- v0.1.0: "Custom Font (MI)" is its own surface now: separate catalog pick
    -- (MIFontName, independent of the feature font) + own size via the row's
    -- right-click. Toggle snapshots + restores the main window's text.
    local miRow = configCheckbox(uiPanel, "Custom Font (MI)", KoffeeOptions.MIFontOn, function(v)
        KoffeeOptions.MIFontOn = v
        Theme.applyMIFont(window, v and Theme.loadFeiFont(KoffeeOptions.MIFontName) or nil,
            v and KoffeeOptions.MIFontSize or nil)
    end)
    rightClickSettings(miRow.row, "Custom Font (MI)", function(menu)
        menu:slider("Font Size", 8, 28, KoffeeOptions.MIFontSize, 0, function(v)
            KoffeeOptions.MIFontSize = v
            if KoffeeOptions.MIFontOn then
                Theme.applyMIFont(window, Theme.loadFeiFont(KoffeeOptions.MIFontName), v)
            end
        end)
    end)
    dropdown(uiPanel, "MI Font", fontOptions, KoffeeOptions.MIFontName, function(v)
        KoffeeOptions.MIFontName = v
        if KoffeeOptions.MIFontOn then
            Theme.applyMIFont(window, Theme.loadFeiFont(v), KoffeeOptions.MIFontSize)
        end
    end)
    -- v0.11.0: repaint the menu itself. One row per palette role; the sweep that
    -- applies them lives next to registerConfig("options").
    local uiColorsPanel = panel(root, "UI Colors")
    local function colorRow(label, key)
        local row = new("Frame", {
            Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1,
            ZIndex = 33, Parent = uiColorsPanel,
        })
        new("TextLabel", {
            Text = label, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Body,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.new(0, 0, 0, 0), Size = UDim2.new(1, -24, 1, 0),
            ZIndex = 34, Parent = row,
        })
        attachSingleSwatch(row, KoffeeOptions.UIColors[key],
            function(c) KoffeeOptions.UIColors[key] = c end)
    end
    colorRow("Accent",         "Accent")
    colorRow("Background",     "Background")
    colorRow("Panel",          "Panel")
    colorRow("Panel Elevated", "PanelElevated")
    colorRow("Border",         "Border")
    colorRow("Text",           "Text")
    colorRow("Text Muted",     "TextMuted")

    -- Ignore Friends: friends are excluded from ESP + aimbot + silent + trigger.
    configCheckbox(card, "Ignore Friends", Shared.IgnoreFriends, function(v)
        Shared.IgnoreFriends = v
    end)

    -- v0.0.95 UNLOAD KOFFEE. Confirm popup then a clean tear-down: disables
    -- every module (their OnDisable fires so state restores), destroys the UI
    -- + toast + hud + background (blur/dim/snow), destroys sound instances,
    -- restores camera + mouse, unbinds our RenderStep binds, and flips a
    -- global unloaded flag so any residual loops early-return.
    local function unloadKoffee()
        -- 1. flip every enabled module OFF so their OnDisable cleanup runs
        for id, m in pairs(Modules) do
            if m.Enabled then pcall(toggleModule, id) end
        end
        -- 2. explicit combat state reset (silent hook stays installed for the
        -- session: can't un-hookmetamethod: but its body early-returns on
        -- Combat.Silent.Enabled = false, so it becomes a no-op).
        -- v0.1.0: Combat lives in its own IIFE; reach it via the Shared export.
        local combat = Shared.Combat
        if combat then
            combat.Silent.Enabled  = false
            combat.Aim.Enabled     = false
            combat.Trigger.Enabled = false
        end
        -- 3. unbind our RenderStep bindings
        pcall(function() RunService:UnbindFromRenderStep(KID.ctx.bind) end)
        pcall(function() RunService:UnbindFromRenderStep("KSpinbot") end)
        pcall(function() RunService:UnbindFromRenderStep("KThirdPerson") end)
        -- 4. destroy every UI surface we own
        pcall(function() screen:Destroy() end)
        pcall(function() popupScreen:Destroy() end)
        pcall(function() blur:Destroy() end)
        -- v0.9.0: the world-FX / hit-FX hosts live on the Camera, not under
        -- `screen`, so those three Destroys miss them. Sweep everything KID tracked
        -- (the same list a re-exec clears) instead of naming surfaces one by one.
        pcall(function()
            for _, inst in ipairs(KID.ctx.instances or {}) do
                pcall(function() inst:Destroy() end)
            end
            KID.ctx.instances = {}
        end)
        -- 5. destroy any sound instances we created
        local combatSounds = Shared.CombatSounds
        pcall(function() if combatSounds then combatSounds.hit:Destroy() end end)
        pcall(function() if combatSounds then combatSounds.kill:Destroy() end end)
        -- 6. restore camera + mouse to game defaults
        pcall(function()
            local cam = Workspace.CurrentCamera
            if cam then cam.CameraType = Enum.CameraType.Custom end
        end)
        UserInputService.MouseBehavior    = Enum.MouseBehavior.Default
        UserInputService.MouseIconEnabled = true
        -- 7. kill every surviving loop. v0.22.0: bumping the generation ends the
        -- ones a re-exec would otherwise leave running against a dead run too.
        if getgenv then getgenv().KoffeeUnloaded = true end
        Koffee._unloaded = true
        KID.ctx.gen = (KID.ctx.gen or 0) + 1
    end
    -- confirm popup: centered on popupScreen so it survives the window fade
    -- + can be seen even if the user closes the menu underneath.
    local function showUnloadConfirm()
        local pS = popupScreen
        if not (pS and pS.Parent) then return end
        local dim = new("Frame", {
            Name = "KUnloadDim",
            Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = Color3.new(0, 0, 0),
            BackgroundTransparency = 0.55, BorderSizePixel = 0,
            ZIndex = 100, Parent = pS,
        })
        local box = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0),
            Size = UDim2.new(0, 320, 0, 148),
            BackgroundColor3 = Theme.Palette.Panel, BorderSizePixel = 0,
            ZIndex = 101, Parent = dim,
        }, { corner(Theme.Radius.Medium), stroke(Theme.Palette.BorderSubtle) })
        new("TextLabel", {
            Text = "Unload Koffee?", FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Header,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1,
            Position = UDim2.new(0, 16, 0, 12), Size = UDim2.new(1, -32, 0, 18),
            TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 102, Parent = box,
        })
        new("TextLabel", {
            Text = "Every feature disables, the UI is removed. Re-run the loader to bring Koffee back.",
            FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
            Position = UDim2.new(0, 16, 0, 36), Size = UDim2.new(1, -32, 0, 44),
            TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
            TextWrapped = true, ZIndex = 102, Parent = box,
        })
        local cancel = new("TextButton", {
            Text = "Cancel", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            AutoButtonColor = false, TextColor3 = Theme.Palette.TextMuted,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0,
            AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -108, 1, -14),
            Size = UDim2.new(0, 88, 0, 28), ZIndex = 102, Parent = box,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        local confirm = new("TextButton", {
            Text = "Unload", FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
            AutoButtonColor = false, TextColor3 = Theme.Palette.Danger or Color3.fromRGB(220, 90, 90),
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0,
            AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -14, 1, -14),
            Size = UDim2.new(0, 88, 0, 28), ZIndex = 102, Parent = box,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        cancel.MouseButton1Click:Connect(function() dim:Destroy() end)
        confirm.MouseButton1Click:Connect(function() dim:Destroy(); pcall(unloadKoffee) end)
    end
    local unloadBtn = new("TextButton", {
            Text = "Unload Koffee", FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
        AutoButtonColor = false, TextColor3 = Theme.Palette.Danger or Color3.fromRGB(220, 90, 90),
        BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
        BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 30), ZIndex = 36, Parent = card,
    }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
    unloadBtn.MouseButton1Click:Connect(showUnloadConfirm)
end)

-- CONFIGS TAB (v0.0.34): save / load / delete / auto-load per game
-- CUSTOM FEATURES (v0.14.0). User-wired node graph: blocks read game state,
-- transform it, draw it. Read-only and depth-capped, so a bad graph is a visual
-- bug, never a crash. Evaluation carries a context so a subgraph under For Each
-- Player runs once per player with its own cached values and its own GUI copies.
Koffee.Custom = { Enabled = true, Scale = "1x", Nodes = {} }
registerConfig("custom", Koffee.Custom)
;(function()
    local CF = Koffee.Custom
    local layer, vis, st = nil, {}, {}
