    -- :: transforms ::
    KINDS.Visible = {
        blurb = "Can you see them?",
        ins = { { key = "player", type = "player", label = "Player" } },
        outs = { bool = true, number = true },
        opts = { MaxDistance = 0, Invert = false },
        eval = function(o, ins)
            local plr = ins.player and ins.player.player
            local d, part = playerAt(plr)
            -- no target answers false even under Invert, or an empty graph would
            -- sit there permanently reading VISIBLE
            if not part then return { bool = false, number = 0 } end
            local cam = Workspace.CurrentCamera
            local seen
            if (o.MaxDistance or 0) > 0 and d > o.MaxDistance then
                seen = false
            else
                local rp = RaycastParams.new()
                rp.FilterType = Enum.RaycastFilterType.Exclude
                rp.FilterDescendantsInstances = { plr.Character, LocalPlayer.Character, cam }
                local from = cam.CFrame.Position
                seen = Workspace:Raycast(from, part.Position - from, rp) == nil
            end
            if o.Invert then seen = not seen end
            return { bool = seen, number = d }
        end,
        ui = function(api, o)
            api:slider("Max Distance", 0, 5000, o.MaxDistance, 0, function(v) o.MaxDistance = v end)
            api:toggle("Invert", o.Invert, function(v) o.Invert = v end)
        end,
    }

    KINDS.Info = {
        blurb = "Reads a detail off a player",
        ins = { { key = "player", type = "player", label = "Player" } },
        outs = { text = true, number = true, bool = true },
        opts = { Field = "Name", Decimals = 0 },
        eval = function(o, ins)
            local plr = ins.player and ins.player.player
            if not plr then return { text = "", number = 0, bool = false } end
            local ch = plr.Character
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            -- v0.40.0: humanoid state. Grounded reads FloorMaterial (Air =
            -- airborne); State names the GetState enum.
            -- v0.43.2: state leads FloorMaterial. Jumping/Freefall flip the
            -- frame you press jump; FloorMaterial lags panels behind takeoff.
            local grounded = false
            if hum then
                local ok, st = pcall(function() return hum:GetState() end)
                if ok and (st == Enum.HumanoidStateType.Jumping
                    or st == Enum.HumanoidStateType.Freefall) then
                    grounded = false
                else
                    local ok2, fm = pcall(function() return hum.FloorMaterial end)
                    grounded = ok2 and fm ~= Enum.Material.Air
                end
            end
            local f, num, txt = o.Field, nil, nil
            if f == "Name" then txt = plr.Name
            elseif f == "Display Name" then txt = plr.DisplayName
            elseif f == "Team" then txt = plr.Team and plr.Team.Name or "none"
            elseif f == "Distance" then num = (playerAt(plr)) or 0
            elseif f == "Health" then num = hum and hum.Health or 0
            elseif f == "Max Health" then num = hum and hum.MaxHealth or 0
            elseif f == "Health %" then
                local mh = hum and hum.MaxHealth or 0
                num = (hum and mh > 0) and (hum.Health / mh * 100) or 0
            elseif f == "Health 0-1" then
                local mh = hum and hum.MaxHealth or 0
                num = (hum and mh > 0) and (hum.Health / mh) or 0
            elseif f == "State" then
                local ok, st = pcall(function() return hum and hum:GetState() end)
                txt = (ok and st and st.Name) or "none"
            elseif f == "Grounded" then
                num, txt = grounded and 1 or 0, grounded and "yes" or "no"
            elseif f == "Airborne" then
                num, txt = (not grounded) and 1 or 0, (not grounded) and "yes" or "no"
            end
            if num then
                local m = 10 ^ math.max(math.floor(o.Decimals or 0), 0)
                txt = tostring(math.floor(num * m + 0.5) / m)
            end
            -- v0.42.0: bool follows the field. (The old one-liner read
            -- `(A and B) or C`: precedence kept it true on the ground.)
            local gate = grounded
            if f == "Airborne" then gate = not grounded end
            return { text = txt or "", number = num or 0, bool = gate }
        end,
        ui = function(api, o)
            api:dropdown("Field", { "Name", "Display Name", "Team", "Distance",
                "Health", "Max Health", "Health %", "Health 0-1",
                "State", "Grounded", "Airborne" },
                o.Field, function(v) o.Field = v end)
            api:slider("Decimals", 0, 3, o.Decimals, 0, function(v) o.Decimals = v end)
            api:label("State = Running, Jumping, Freefall... bool = gate")
        end,
    }

