    -- a squashed UICorner renders as a stadium, not an ellipse, so Circle cannot
    -- lie flat no matter what you scale it by. This walks segments around a real
    -- ellipse instead, which is what sells a ring as being AROUND something.
    local RING_SEGS = 28
    KINDS.Ring = {
        blurb = "A flat ring that lies around something",
        sink = true, visual = true,
        ins = visIns({ { key = "radius", type = "number", label = "Radius" } }),
        outs = {},
        opts = visOpts({ Radius = 55, Squash = 0.34, Thickness = 2, Segments = 22,
                 Color = Color3.fromRGB(238, 238, 238) }),
        make = function()
            -- zero-size anchored group: children offset from its centre, and the
            -- shared Rotation / Spin handling turns the whole ring for free
            local g = new("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1,
                Size = UDim2.new(0, 0, 0, 0), ZIndex = 17, Parent = ensureLayer(),
            })
            for _ = 1, RING_SEGS do
                new("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5), BorderSizePixel = 0,
                    BackgroundColor3 = Color3.new(1, 1, 1), Visible = false,
                    ZIndex = 17, Parent = g,
                })
            end
            g:SetAttribute("KUserColor", true)
            for _, d in ipairs(g:GetDescendants()) do d:SetAttribute("KUserColor", true) end
            return g
        end,
        paint = function(g, o, ins, node, ctx, dt)
            if not placeVis(g, o, ins, node, ctx, dt) then return end
            local r = math.max((ins.radius and ins.radius.number) or o.Radius, 1)
            local sq = math.clamp(o.Squash or 0.34, 0.02, 1)
            local col = (ins.color and ins.color.color) or o.Color
            local tr = 1 - math.clamp(o.Opacity or 1, 0, 1)
            local segs = g:GetChildren()
            local n = math.clamp(math.floor(o.Segments or 22), 6, RING_SEGS)
            local used = 0
            for i = 1, n do
                local a0 = (i - 1) / n * math.pi * 2
                local a1 = i / n * math.pi * 2
                local x0, y0 = math.cos(a0) * r, math.sin(a0) * r * sq
                local x1, y1 = math.cos(a1) * r, math.sin(a1) * r * sq
                local dx, dy = x1 - x0, y1 - y0
                used = used + 1
                local f = segs[used]
                if f then
                    f.Size = UDim2.new(0, math.sqrt(dx * dx + dy * dy) + 1,
                                       0, math.max(o.Thickness or 2, 0.5))
                    f.Position = UDim2.new(0, (x0 + x1) * 0.5, 0, (y0 + y1) * 0.5)
                    f.Rotation = math.deg(math.atan2(dy, dx))
                    f.BackgroundColor3 = col
                    f.BackgroundTransparency = tr
                    f.Visible = true
                end
            end
            for i = used + 1, #segs do segs[i].Visible = false end
        end,
        ui = function(api, o)
            api:section("shape")
            api:slider("Radius", 1, 600, o.Radius, 0, function(v) o.Radius = v end)
            api:slider("Squash", 0.02, 1, o.Squash, 2, function(v) o.Squash = v end)
            api:label("Squash flattens the ring so it lies around something")
            api:slider("Thickness", 0.5, 20, o.Thickness, 1, function(v) o.Thickness = v end)
            api:slider("Smoothness", 6, 28, o.Segments, 0, function(v) o.Segments = v end)
            api:section("fill")
            api:swatch("Colour", o.Color, function(c) o.Color = c end)
            visUiTail(api, o)
        end,
    }

    -- :: 3D ::
    -- Screen-space blocks draw a flat overlay: it never tilts, never sits behind
    -- anything, and a ring can only ever be an ellipse pretending. These build real
    -- Parts instead. Parented to the Camera, so they never replicate and sit outside
    -- the tree a passive AC walks. The trade is honest: real geometry is occluded by
    -- real geometry, which the overlay blocks never were.
    local function part3(parent)
        local p = Instance.new("Part")
        p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch = true, false, false, false
        p.CastShadow = false
        p.Material = Enum.Material.Neon
        p.TopSurface = Enum.SurfaceType.Smooth
        p.BottomSurface = Enum.SurfaceType.Smooth
        p.Size = Vector3.new(0.1, 0.1, 0.1)
        p.Parent = parent
        return p
    end

    -- one Model per node: Destroy on it frees every segment, which is exactly what
    -- the existing `vis` sweep already does for GUI blocks. Model rather than Folder
    -- because a Highlight can only adorn a Model or a BasePart.
    local function rig3(n)
        local f = KID.track(Instance.new("Model"))
        f.Name = KID.name("cf3")
        for _ = 1, n do part3(f) end
        f.Parent = Workspace.CurrentCamera
        return f
    end

    -- THROUGH WALLS. A BasePart has no way to skip the depth test, and adornment
    -- AlwaysOnTop is a long-standing engine bug (it still gets partially occluded),
    -- so the only reliable route is a Highlight in AlwaysOnTop DepthMode drawing the
    -- model's silhouette over everything.
    -- The catch: Roblox renders at most 31 Highlights ENGINE-WIDE and silently drops
    -- ALL of them past that, chams included. So this keeps a hard budget well under
    -- the cap and degrades to plain occluded geometry instead of taking the last slot.
    local HL_MAX = 12
    local hls = setmetatable({}, { __mode = "k" })
    local function through3(f, want, col, tr)
        local h = hls[f]
        if not want then
            if h then h:Destroy(); hls[f] = nil end
            return false
        end
        if not h then
            local n = 0
            for m, x in pairs(hls) do
                if m.Parent and x.Parent then n = n + 1 else hls[m] = nil end
            end
            if n >= HL_MAX then return false end
            h = Instance.new("Highlight")
            h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            h.OutlineTransparency = 1
            h.Adornee = f
            h.Parent = f
            hls[f] = h
        end
        h.FillColor = col
        h.FillTransparency = tr
        h.Enabled = true
        return true
    end

    local function hide3(f)
        for _, p in ipairs(f:GetChildren()) do
            if p:IsA("BasePart") then p.Transparency = 1 end
        end
        local h = hls[f]
        if h then h.Enabled = false end
    end

    local function w3Ins(extra)
        local t = {}
        for _, e in ipairs(extra or {}) do t[#t + 1] = e end
        t[#t + 1] = { key = "at",    type = "world", label = "World Position" }
        t[#t + 1] = { key = "color", type = "color", label = "Colour" }
        t[#t + 1] = { key = "show",  type = "bool",  label = "Show When" }
        return t
    end

    local function w3Opts(extra)
        local o = { Height = 0, Transparency = 0, ThroughWalls = false,
                    Spin = false, SpinSpeed = 60 }
        for k, v in pairs(extra or {}) do o[k] = v end
        return o
    end

    -- returns the world anchor, or nil when the block should not draw
    local function place3(f, o, ins)
        if ins.show and (ins.show.bool ~= true) then return nil end
        local at = ins.at and ins.at.world
        if not at then return nil end
        local cam = Workspace.CurrentCamera
        if cam and f.Parent ~= cam then pcall(function() f.Parent = cam end) end
        return at + Vector3.new(0, o.Height or 0, 0)
    end

    local function w3UiTail(api, o)
        api:toggle("Through Walls", o.ThroughWalls, function(v) o.ThroughWalls = v end)
        api:slider("Height", -20, 20, o.Height, 2, function(v) o.Height = v end)
        api:slider("Transparency", 0, 1, o.Transparency, 2, function(v) o.Transparency = v end)
        api:toggle("Spin", o.Spin, function(v) o.Spin = v end)
        api:slider("Spin Speed", -720, 720, o.SpinSpeed, 0, function(v) o.SpinSpeed = v end)
    end

    local R3_SEGS = 32
    KINDS["3D Ring"] = {
        blurb = "A real ring in the world, lying flat around something",
        sink = true, visual = true,
        ins = w3Ins({ { key = "radius", type = "number", label = "Radius" } }),
        outs = {},
        opts = w3Opts({ Radius = 4, Thickness = 0.18, Segments = 24, Tilt = 0,
                 Color = Color3.fromRGB(120, 220, 255) }),
        make = function() return rig3(R3_SEGS) end,
        paint = function(f, o, ins, node, ctx, dt)
            local at = place3(f, o, ins)
            if not at then hide3(f) return end
            local r = math.max((ins.radius and ins.radius.number) or o.Radius, 0.05)
            local col = (ins.color and ins.color.color) or o.Color
            local n = math.clamp(math.floor(o.Segments or 24), 6, R3_SEGS)
            local th = math.max(o.Thickness or 0.18, 0.02)
            local tr = math.clamp(o.Transparency or 0, 0, 1)
            local sl = slot(node, ctx)
            sl.spin = (sl.spin or 0) + (o.Spin and (o.SpinSpeed or 60) * (dt or 0) or 0)
            local base = CFrame.new(at)
                * CFrame.Angles(0, math.rad(sl.spin), 0)
                * CFrame.Angles(math.rad(o.Tilt or 0), 0, 0)
            -- 6% overlap, otherwise the straight chords leave visible gaps at the joints
            local segLen = (2 * math.pi * r / n) * 1.06
            through3(f, o.ThroughWalls, col, tr)
            local kids = f:GetChildren()
            for i = 1, n do
                local pt = kids[i]
                if pt and pt:IsA("BasePart") then
                    local a = (i - 0.5) / n * math.pi * 2
                    local off = Vector3.new(math.cos(a) * r, 0, math.sin(a) * r)
                    local tan = Vector3.new(-math.sin(a), 0, math.cos(a))
                    pt.Size = Vector3.new(th, th, segLen)
                    pt.CFrame = base * CFrame.lookAt(off, off + tan)
                    pt.Color = col
                    pt.Transparency = tr
                end
            end
            for i = n + 1, #kids do
                if kids[i]:IsA("BasePart") then kids[i].Transparency = 1 end
            end
        end,
        ui = function(api, o)
            api:slider("Radius", 0.2, 40, o.Radius, 2, function(v) o.Radius = v end)
            api:slider("Thickness", 0.02, 2, o.Thickness, 2, function(v) o.Thickness = v end)
            api:slider("Smoothness", 6, 32, o.Segments, 0, function(v) o.Segments = v end)
            api:slider("Tilt", -90, 90, o.Tilt, 0, function(v) o.Tilt = v end)
            api:swatch("Colour", o.Color, function(c) o.Color = c end)
            w3UiTail(api, o)
        end,
    }

    -- 12 cube edges as sign triples: axis the edge runs along, then the corner it
    -- sits on in the other two
    local BOX_EDGES = {
        { "x", -1, -1 }, { "x", -1, 1 }, { "x", 1, -1 }, { "x", 1, 1 },
        { "y", -1, -1 }, { "y", -1, 1 }, { "y", 1, -1 }, { "y", 1, 1 },
        { "z", -1, -1 }, { "z", -1, 1 }, { "z", 1, -1 }, { "z", 1, 1 },
    }
    KINDS["3D Box"] = {
        blurb = "A wireframe box in the world",
        sink = true, visual = true,
        ins = w3Ins({ { key = "size", type = "number", label = "Size" } }),
        outs = {},
        opts = w3Opts({ Size = 5, Thickness = 0.12, Tall = 1.8,
                 Color = Color3.fromRGB(255, 176, 46) }),
        make = function() return rig3(#BOX_EDGES) end,
        paint = function(f, o, ins, node, ctx, dt)
            local at = place3(f, o, ins)
            if not at then hide3(f) return end
            local w = math.max((ins.size and ins.size.number) or o.Size, 0.1)
            local h = w * math.max(o.Tall or 1.8, 0.05)
            local col = (ins.color and ins.color.color) or o.Color
            local th = math.max(o.Thickness or 0.12, 0.02)
            local tr = math.clamp(o.Transparency or 0, 0, 1)
            local sl = slot(node, ctx)
            sl.spin = (sl.spin or 0) + (o.Spin and (o.SpinSpeed or 60) * (dt or 0) or 0)
            local base = CFrame.new(at) * CFrame.Angles(0, math.rad(sl.spin), 0)
            local hx, hy, hz = w * 0.5, h * 0.5, w * 0.5
            through3(f, o.ThroughWalls, col, tr)
            local kids = f:GetChildren()
            for i, e in ipairs(BOX_EDGES) do
                local pt = kids[i]
                if pt and pt:IsA("BasePart") then
                    local ax, s1, s2 = e[1], e[2], e[3]
                    local off, size
                    if ax == "x" then
                        off = Vector3.new(0, s1 * hy, s2 * hz)
                        size = Vector3.new(w + th, th, th)
                    elseif ax == "y" then
                        off = Vector3.new(s1 * hx, 0, s2 * hz)
                        size = Vector3.new(th, h + th, th)
                    else
                        off = Vector3.new(s1 * hx, s2 * hy, 0)
                        size = Vector3.new(th, th, w + th)
                    end
                    pt.Size = size
                    pt.CFrame = base * CFrame.new(off)
                    pt.Color = col
                    pt.Transparency = tr
                end
            end
        end,
        ui = function(api, o)
            api:slider("Width", 0.2, 40, o.Size, 2, function(v) o.Size = v end)
            api:slider("Height x Width", 0.1, 6, o.Tall, 2, function(v) o.Tall = v end)
            api:slider("Thickness", 0.02, 2, o.Thickness, 2, function(v) o.Thickness = v end)
            api:swatch("Colour", o.Color, function(c) o.Color = c end)
            w3UiTail(api, o)
        end,
    }

