            api:slider("Up / Down", -200, 200, o.UpDown, 0, function(v) o.UpDown = v end)
            api:label("Set = held every frame. Add = one kick, re-arms on land")
            api:label("Wire Direction (a world point) to steer; else it follows the camera")
