    }
    local KSET_NAMES, KSET_BY = {}, {}
    for _, e in ipairs(KSET) do KSET_NAMES[#KSET_NAMES + 1] = e.name; KSET_BY[e.name] = e end
    KINDS["Koffee Set"] = {
