    -- v0.39.0 Stage 3: build a buffer from a saved schema (template + your live values)
    -- and hand it to Fire Remote via a buffer wire. Scaffold = Position -> x/y/z fields.
    local BUFSIZE = { u8 = 1, i8 = 1, u16 = 2, i16 = 2, u32 = 4, i32 = 4, f32 = 4, f64 = 8, string = 0 }
    KINDS["Build Buffer"] = {
        blurb = "Builds a buffer from a saved schema, patched with your live values -> Fire Remote",
        ins = { { key = "world", type = "world", label = "Position" }, { key = "num", type = "number", label = "Number" } },
        outs = { buffer = true, text = true },
        opts = { Schema = "", NumField = "" },
        eval = function(o, ins, ctx, node)
            local s = slot(node, ctx)
            if s.schemaName ~= o.Schema then
                s.schemaName, s.tmpl, s.fields = o.Schema, nil, nil
                if o.Schema ~= "" and readfile and isfile then
                    local p = "Koffee/buffers/" .. o.Schema .. ".json"
                    if isfile(p) then
                        local ok, txt = pcall(readfile, p)
                        local dok, data = false, nil
                        if ok then dok, data = pcall(function() return game:GetService("HttpService"):JSONDecode(txt) end) end
                        if dok and type(data) == "table" then
                            s.fields = (type(data.fields) == "table") and data.fields or data
                            if type(data.template) == "string" then
                                local out = {}
                                for h in data.template:gmatch("%x%x") do out[#out + 1] = string.char(tonumber(h, 16)) end
                                s.tmpl = table.concat(out)
                            end
                        end
                    end
                end
            end
            if not s.tmpl then return { buffer = nil, text = "No template" } end
            local ok, b = pcall(buffer.fromstring, s.tmpl)
            if not ok then return { buffer = nil, text = "Bad template" } end
            local n = buffer.len(b)
            local function w(off, ty, val)
                if not val or off + (BUFSIZE[ty] or 4) > n then return end
                pcall(function()
                    if ty == "u8" then buffer.writeu8(b, off, val)
                    elseif ty == "i8" then buffer.writei8(b, off, val)
                    elseif ty == "u16" then buffer.writeu16(b, off, val)
                    elseif ty == "i16" then buffer.writei16(b, off, val)
                    elseif ty == "u32" then buffer.writeu32(b, off, val)
                    elseif ty == "i32" then buffer.writei32(b, off, val)
                    elseif ty == "f32" then buffer.writef32(b, off, val)
                    elseif ty == "f64" then buffer.writef64(b, off, val) end
                end)
            end
            local wpos = ins.world and ins.world.world
            local num = ins.num and ins.num.number
            for _, fd in ipairs(s.fields or {}) do
                local nm = tostring(fd.name or ""):lower()
                if wpos and (nm == "x" or nm:match("^x@")) then w(fd.off, fd.type, wpos.X)
                elseif wpos and (nm == "y" or nm:match("^y@")) then w(fd.off, fd.type, wpos.Y)
                elseif wpos and (nm == "z" or nm:match("^z@")) then w(fd.off, fd.type, wpos.Z)
                elseif num and o.NumField ~= "" and fd.name == o.NumField then w(fd.off, fd.type, num)
                end
            end
            return { buffer = b, text = o.Schema }
        end,
        ui = function(api, o)
            local names = {}
            pcall(function()
                if listfiles and isfolder and isfolder("Koffee/buffers") then
                    for _, p in ipairs(listfiles("Koffee/buffers")) do
                        local nm = tostring(p):match("([^/\\]+)%.json$")
                        if nm then names[#names + 1] = nm end
                    end
                end
            end)
            if #names == 0 then names = { "(save one in Buffer Lab)" } end
            api:dropdown("Schema", names, o.Schema ~= "" and o.Schema or names[1], function(v) o.Schema = v end)
            api:text("Number -> field", o.NumField, function(v) o.NumField = v end)
            api:label("Position fills x/y/z fields; Number fills the named field")
            api:label("Wire the buffer output into a Fire Remote arg set to Buffer")
        end,
    }

    KINDS.Note = {
        blurb = "A label on the canvas. Draws nothing in game",
        ins = {}, outs = {},
        opts = { Text = "Notes" },
        ui = function(api, o) api:text("Note", o.Text, function(v) o.Text = v end) end,
    }

    -- :: evaluation ::
    local frameDt = 1 / 60
    local resolveIns, evalNode
    resolveIns = function(node, K, cache, depth, ctx)
        local ins = {}
        for _, s in ipairs(K.ins) do
            local ref = node.wires and node.wires[s.key]
            local src = ref and nodeById(ref)
            if src then ins[s.key] = evalNode(src, cache, depth + 1, ctx) end
        end
        return ins
    end
    -- memoized per context, depth-capped so a wire loop returns empty instead of
    -- hanging the client
    evalNode = function(node, cache, depth, ctx)
        local bag = cache[ctx.key]
        if not bag then bag = {}; cache[ctx.key] = bag end
        local hit = bag[node.id]
        if hit ~= nil then return hit end
        if depth > 16 then return {} end
        local K = KINDS[node.kind]
        if not K then return {} end
        bag[node.id] = {}
        local ins = resolveIns(node, K, cache, depth, ctx)
        local out = ins
        if K.eval then
            local ok, r = pcall(K.eval, node.opts, ins, ctx, node, frameDt)
            out = (ok and type(r) == "table") and r or {}
        end
        bag[node.id] = out
        return out
    end

    -- which For Each block, if any, a sink hangs off. Memoized per frame.
    local function feOf(node, memo, depth)
        if depth > 16 then return nil end
        local hit = memo[node.id]
        if hit ~= nil then return hit or nil end
        memo[node.id] = false
        if node.kind == "For Each Player" then memo[node.id] = node; return node end
        local K = KINDS[node.kind]
        if K then
            for _, s in ipairs(K.ins) do
                local ref = node.wires and node.wires[s.key]
                local src = ref and nodeById(ref)
                if src then
                    local f = feOf(src, memo, depth + 1)
                    if f then memo[node.id] = f; return f end
                end
            end
        end
        return nil
    end
    local function playersFor(o)
        local out = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer then
                local ally = isTeammate and isTeammate(p) or false
                local ok = true
                if o.Filter == "Enemies Only" and ally then ok = false end
                if o.Filter == "Team Only" and not ally then ok = false end
                local d = playerAt(p)
                if ok and o.AliveOnly then
                    local hum = p.Character and p.Character:FindFirstChildOfClass("Humanoid")
                    if not (hum and hum.Health > 0) then ok = false end
                end
                if ok and (o.MaxDistance or 0) > 0 and (not d or d > o.MaxDistance) then ok = false end
                if ok then out[#out + 1] = { key = tostring(p.UserId), player = p, d = d or 1e9 } end
            end
        end
        table.sort(out, function(a, b) return a.d < b.d end)
        while #out > math.max(math.floor(o.MaxCount or 24), 1) do table.remove(out) end
        return out
    end

    guiFor = function(node, K, ctx)
        local key = ckey(node, ctx)
        local g = vis[key]
        if g and g.Parent then
            -- v0.22.0: revived inside its grace window: unhide. paint runs after
            -- this and re-hides if the block's own logic wants it hidden.
            if visGone[key] then
                visGone[key] = nil
                pcall(function() g.Visible = true end)
            end
            return g
        end
        local ok, made = pcall(K.make)
        if not ok then return nil end
        vis[key] = made
        visGone[key] = nil
        return made
    end

    -- :: design mode ::
    -- v0.25.0: direct manipulation of the live output. Click a drawn widget,
    -- then drag to move, pull a handle to resize, or use the arc to rotate.
    -- Writes back into node.opts, so gizmo and sliders are two views of one value.
    local DM = { on = false, sel = nil, key = nil, drag = nil }

    -- what a resize handle edits, per block kind. Kinds absent here move and
    -- rotate but do not resize.
    local DM_SIZE = {
        Box   = { w = "W", h = "H" },  Group = { w = "W", h = "H" },
        Bar   = { w = "W", h = "H" },  Image = { w = "W", h = "H" },
        Circle = { r = "Radius" },     Ring  = { r = "Radius" },
        Text  = { s = "Size" },
    }
    local DM_HANDLES = { "nw", "n", "ne", "w", "e", "sw", "s", "se" }
    local dmGui, dmBox, dmDots, dmRot, dmTip, dmBan = nil, nil, {}, nil, nil, nil

    local function dmBuild()
        if dmGui and dmGui.Parent then return end
        dmGui = KID.track(new("Frame", {
            Name = KID.name("dm"), Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1, Visible = false, ZIndex = 60, Parent = screen,
        }))
        dmBox = new("Frame", {
            BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 61, Parent = dmGui,
        }, { stroke(Theme.Palette.Accent) })
        for _, h in ipairs(DM_HANDLES) do
            dmDots[h] = new("Frame", {
                Name = h, Size = UDim2.new(0, 8, 0, 8),
                AnchorPoint = Vector2.new(0.5, 0.5), BorderSizePixel = 0,
                BackgroundColor3 = Theme.Palette.Accent, ZIndex = 62, Parent = dmGui,
            }, { corner(2) })
        end
        dmRot = new("Frame", {
            Size = UDim2.new(0, 10, 0, 10), AnchorPoint = Vector2.new(0.5, 0.5),
            BorderSizePixel = 0, BackgroundColor3 = Theme.Palette.Success,
            ZIndex = 62, Parent = dmGui,
        }, { pillCorner() })
        dmTip = new("TextLabel", {
            FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundColor3 = Theme.Palette.Panel,
            BackgroundTransparency = 0.15, BorderSizePixel = 0, Text = "",
            AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 0, 16),
            AnchorPoint = Vector2.new(0.5, 1), ZIndex = 63, Parent = dmGui,
        }, { corner(4), new("UIPadding", { PaddingLeft = UDim.new(0, 5),
             PaddingRight = UDim.new(0, 5) }) })
        -- v0.26.1: banner. Without it, design mode with nothing selected looked
        -- identical to design mode being off, which read as "it does nothing".
        dmBan = new("TextLabel", {
            Text = "Design Mode: Click a widget to select it, Esc to exit",
            FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundColor3 = Theme.Palette.Panel,
            BackgroundTransparency = 0.1, BorderSizePixel = 0,
            AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 0, 22),
            AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 44),
            ZIndex = 63, Parent = dmGui,
        }, { corner(6), stroke(Theme.Palette.Accent),
             new("UIPadding", { PaddingLeft = UDim.new(0, 10),
                                PaddingRight = UDim.new(0, 10) }) })
    end

    -- v0.26.1: a full-screen frame at Position 0,0 does NOT report AbsolutePosition
    -- (0,0) here: IgnoreGuiInset drift, same trap popupOffsetFor works around.
    -- Everything below works in LAYER-LOCAL pixels, which is also GetMouseLocation's
    -- space, so hit tests and gizmo placement agree. This was the "clicks miss" bug.
    local function dmOrigin()
        local f = dmGui or layer
        return f and f.AbsolutePosition or Vector2.new(0, 0)
    end

    -- node id out of a "id|ctx" vis key
    local function dmNodeOf(key)
        local id = tonumber(key:match("^(%d+)|"))
        return id and nodeById(id) or nil
    end
    local function dmRect(g)
        if not (g and g.Parent) then return nil end
        local p, s, o = g.AbsolutePosition, g.AbsoluteSize, dmOrigin()
        return p.X - o.X, p.Y - o.Y, s.X, s.Y
    end
    local function dmInside(x, y, rx, ry, rw, rh, pad)
        pad = pad or 0
        return x >= rx - pad and x <= rx + rw + pad and y >= ry - pad and y <= ry + rh + pad
    end

    -- topmost drawn widget under the cursor. Hit test is the UNROTATED rect:
    -- AbsolutePosition/Size ignore Rotation, so a spun block grabs by its box.
    local function dmPick(x, y)
        local bk, bz = nil, -1
        for key, g in pairs(vis) do
            if g and g.Parent and g.Visible then
                local rx, ry, rw, rh = dmRect(g)
                if rx and dmInside(x, y, rx, ry, rw, rh) then
                    local z = g.ZIndex or 0
                    if z >= bz then bk, bz = key, z end
                end
            end
        end
        return bk
    end

    local function dmSelGui()
        return DM.key and vis[DM.key] or nil
    end
    local function dmClear()
        DM.sel, DM.key, DM.drag = nil, nil, nil
        if dmGui then dmGui.Visible = false end
    end

    -- follow the selected widget. Runs at the end of the frame, after paint.
    local function dmSync()
        if not DM.on then if dmGui then dmGui.Visible = false end return end
        dmBuild()
        -- v0.26.1: the frame stays visible for the banner even with no selection.
        -- Only the box, handles and readout follow a selected widget.
        dmGui.Visible = true
        local g = dmSelGui()
        local node = DM.sel and nodeById(DM.sel) or nil
        local rx, ry, rw, rh = dmRect(g)
        local has = (g and g.Parent and node and rx) and true or false
        dmBox.Visible = has
        dmRot.Visible = has
        dmTip.Visible = has
        for _, d in pairs(dmDots) do d.Visible = has end
        dmBan.Text = has and "Design Mode: Drag to move, dots resize, Esc to deselect"
            or "design mode: click a widget to select it, esc to exit"
        if not has then return end
        dmBox.Position = UDim2.new(0, rx, 0, ry)
        dmBox.Size = UDim2.new(0, rw, 0, rh)
        local mx, my = rx + rw * 0.5, ry + rh * 0.5
        local px = { nw = { rx, ry }, n = { mx, ry }, ne = { rx + rw, ry },
                     w = { rx, my }, e = { rx + rw, my },
                     sw = { rx, ry + rh }, s = { mx, ry + rh }, se = { rx + rw, ry + rh } }
        local sz = DM_SIZE[node.kind]
        for h, d in pairs(dmDots) do
            d.Visible = sz ~= nil
            d.Position = UDim2.new(0, px[h][1], 0, px[h][2])
        end
        dmRot.Position = UDim2.new(0, mx, 0, ry - 20)
        dmTip.Position = UDim2.new(0, mx, 0, ry - 30)
        dmTip.Text = ("%s  %d,%d"):format(node.kind,
            math.floor(node.opts.OffX or 0), math.floor(node.opts.OffY or 0))
    end

    -- which gizmo part is under the cursor, if any. Handles are anchor-centred,
    -- so their rect is offset by half their size.
    local function dmHandleAt(x, y)
        if not (dmGui and dmGui.Visible) then return nil end
        local o = dmOrigin()
        for h, d in pairs(dmDots) do
            if d.Visible then
                local p = d.AbsolutePosition
                if dmInside(x, y, p.X - o.X, p.Y - o.Y, 8, 8, 5) then return h end
            end
        end
        if dmRot.Visible then
            local rp = dmRot.AbsolutePosition
            if dmInside(x, y, rp.X - o.X, rp.Y - o.Y, 10, 10, 6) then return "rot" end
        end
        return nil
    end

    -- snap the widget's centre to the screen centre lines
    local function dmSnap(v, target)
        return (math.abs(v - target) <= 6) and target or v
    end

    local function dmBegin(x, y)
        local h = dmHandleAt(x, y)
        local node = DM.sel and nodeById(DM.sel) or nil
        if h and node then
            local g = dmSelGui()
            local rx, ry, rw, rh = dmRect(g)
            DM.drag = { mode = (h == "rot") and "rot" or "size", h = h, x = x, y = y,
                        ox = node.opts.OffX or 0, oy = node.opts.OffY or 0,
                        w = node.opts.W, hh = node.opts.H, r = node.opts.Radius,
                        ts = node.opts.Size, rot = node.opts.Rotation or 0,
                        cx = (rx or 0) + (rw or 0) * 0.5, cy = (ry or 0) + (rh or 0) * 0.5 }
            return true
        end
        local g = dmSelGui()
        if g then
            local rx, ry, rw, rh = dmRect(g)
            if rx and dmInside(x, y, rx, ry, rw, rh) and node then
                DM.drag = { mode = "move", x = x, y = y,
                            ox = node.opts.OffX or 0, oy = node.opts.OffY or 0 }
                return true
            end
        end
        local key = dmPick(x, y)
        if key then
            local n = dmNodeOf(key)
            if n then
                DM.sel, DM.key, DM.drag = n.id, key, nil
                -- v0.26.1: point the editor's inspector at whatever you clicked,
                -- so selecting on screen and selecting in the graph are one action
                if Koffee._cfSelect then pcall(Koffee._cfSelect, n.id) end
                return true
            end
        end
        dmClear()
        return false
    end

    local function dmMove(x, y)
        local d = DM.drag
        if not d then return end
        local node = DM.sel and nodeById(DM.sel)
        if not node then return end
        local o = node.opts
        local dx, dy = (x - d.x) / lscale, (y - d.y) / lscale
        if d.mode == "move" then
            local g = dmSelGui()
            o.OffX, o.OffY = d.ox + dx, d.oy + dy
            -- snap the widget's centre to the middle of the screen
            local vp = viewport()
            local rx, ry, rw, rh = dmRect(g)
            if rx and vp then
                local cx, cy = rx + rw * 0.5, ry + rh * 0.5
                o.OffX = o.OffX + (dmSnap(cx, vp.X * 0.5) - cx) / lscale
                o.OffY = o.OffY + (dmSnap(cy, vp.Y * 0.5) - cy) / lscale
            end
            o.OffX, o.OffY = math.floor(o.OffX + 0.5), math.floor(o.OffY + 0.5)
        elseif d.mode == "rot" then
            local a0 = math.atan2(d.y - d.cy, d.x - d.cx)
            local a1 = math.atan2(y - d.cy, x - d.cx)
            o.Rotation = math.floor(d.rot + math.deg(a1 - a0) + 0.5)
        else
            local sz = DM_SIZE[node.kind]
            if not sz then return end
            local h = d.h
            if sz.w then
                -- east/west handles push width, north/south push height. Anchor is
                -- the block's own pivot, so a drag grows around it, not from a corner.
                local sx = (h == "e" or h == "ne" or h == "se") and 1
                    or ((h == "w" or h == "nw" or h == "sw") and -1 or 0)
                local sy = (h == "s" or h == "sw" or h == "se") and 1
                    or ((h == "n" or h == "nw" or h == "ne") and -1 or 0)
                if sx ~= 0 then o.W = math.max(1, math.floor((d.w or 1) + dx * sx + 0.5)) end
                if sy ~= 0 then o.H = math.max(1, math.floor((d.hh or 1) + dy * sy + 0.5)) end
            elseif sz.r then
                local m = (math.abs(dx) > math.abs(dy)) and dx or dy
                local sgn = (h == "e" or h == "se" or h == "s" or h == "ne") and 1 or -1
                o.Radius = math.max(1, math.floor((d.r or 1) + m * sgn + 0.5))
            elseif sz.s then
                o.Size = math.clamp(math.floor((d.ts or 12) + dy * -1 + 0.5), 8, 96)
            end
        end
    end

    Koffee._designMode = function(on)
        DM.on = on == true
        if not DM.on then dmClear(); return end
        dmBuild()            -- build now so the banner shows the instant it's on
        dmGui.Visible = true
        if Shared.setWindowOpen then Shared.setWindowOpen(false) end
    end

    UserInputService.InputBegan:Connect(function(input, gpe)
        if Koffee.dead() or not DM.on or gpe then return end
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            local m = UserInputService:GetMouseLocation()
            dmBegin(m.X, m.Y)
        elseif input.KeyCode == Enum.KeyCode.Escape then
            dmClear()
        elseif DM.sel then
            local node = nodeById(DM.sel)
            local step = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) and 10 or 1
            local k = input.KeyCode
            if node then
                local o = node.opts
                if k == Enum.KeyCode.Left  then o.OffX = (o.OffX or 0) - step
                elseif k == Enum.KeyCode.Right then o.OffX = (o.OffX or 0) + step
                elseif k == Enum.KeyCode.Up    then o.OffY = (o.OffY or 0) - step
                elseif k == Enum.KeyCode.Down  then o.OffY = (o.OffY or 0) + step end
            end
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if Koffee.dead() or not DM.on or not DM.drag then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement then
            local m = UserInputService:GetMouseLocation()
            dmMove(m.X, m.Y)
        end
    end)

    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then DM.drag = nil end
    end)

    RunService.RenderStepped:Connect(function(dt)
        if Koffee.dead() then return end
        frameDt, frameId = dt, frameId + 1
        fpsAcc, fpsN = fpsAcc + dt, fpsN + 1
        if fpsAcc >= 0.25 then FPS = fpsN / fpsAcc; fpsAcc, fpsN = 0, 0 end
        -- v0.24.0: push the design-pixel scale onto the layer once per frame.
        lscale = wantScale()
        local lsc = layer and layer:FindFirstChildOfClass("UIScale")
        if lsc and lsc.Scale ~= lscale then lsc.Scale = lscale end
        local alive = {}
        if CF.Enabled then
            reindex()
            -- v0.22.0: ctxMemo. playersFor ran once per SINK, so five draw blocks
            -- under one For Each Player meant five identical Players sweeps +
            -- distance passes + sorts per frame. Memoised by the For Each node.
            local cache, memo, ctxMemo = {}, {}, {}
            for _, node in ipairs(CF.Nodes) do
                local K = KINDS[node.kind]
                if K and K.sink then
                    local fe = feOf(node, memo, 0)
                    local ctxs
                    if fe then
                        ctxs = ctxMemo[fe.id]
                        if not ctxs then ctxs = playersFor(fe.opts); ctxMemo[fe.id] = ctxs end
                        -- v0.25.0: nothing renders in an empty lobby, so there is
                        -- nothing to grab. Design Mode forces one preview context.
                        if DM.on and #ctxs == 0 then ctxs = { GCTX } end
                    else
                        ctxs = { GCTX }
                    end
                    for _, ctx in ipairs(ctxs) do
                        alive[ckey(node, ctx)] = true
                        -- action blocks (Sound) have no GUI of their own
                        local g = K.make and guiFor(node, K, ctx) or nil
                        if g or not K.make then
                            local ins = resolveIns(node, K, cache, 0, ctx)
                            pcall(K.paint, g, node.opts, ins, node, ctx, dt)
                        end
                    end
                end
            end
        end
        -- v0.22.0: hide first, Destroy after a grace window. A target that blinks
        -- out for one frame (dies, clips out of FOV) used to tear its whole GUI
        -- subtree down and rebuild it next frame: the cost AND the visual pop.
        for key, g in pairs(vis) do
            if alive[key] then
                visGone[key] = nil
            else
                local since = visGone[key]
                if not since then
                    visGone[key] = frameId
                    pcall(function() g.Visible = false end)
                elseif frameId - since > 120 then
                    g:Destroy(); vis[key] = nil; visGone[key] = nil
                end
            end
        end
        for key, v in pairs(st) do
            if v._f ~= frameId then st[key] = nil end
        end
        -- v0.22.0: KEYC keys off UserId, so a long session with lots of unique
        -- players would creep. Full clear every ~10s; rebuild cost is one concat.
        if frameId % 600 == 0 then table.clear(KEYC) end
        dmSync()
    end)

    -- :: graph edits ::
    -- the Text block's single "text" slot became "a" in v0.13.3
    local OPMAP = {
        ["less than"] = "Less Than", ["more than"] = "More Than",
        ["equal to"] = "Equal To", add = "Add", subtract = "Subtract",
        multiply = "Multiply", divide = "Divide", smallest = "Smallest",
        largest = "Largest", difference = "Difference", ["and"] = "And",
        ["or"] = "Or", ["not A"] = "Not A", ["only one"] = "Only One",
        ["becomes yes"] = "Becomes Yes", ["becomes no"] = "Becomes No",
        ["while yes"] = "While Yes", ["Turn On (edge)"] = "Turn On (Edge)",
        ["Turn Off (edge)"] = "Turn Off (Edge)", ["(none)"] = "(None)",
    }
    local function migrate()
        for _, n in ipairs(CF.Nodes) do
            -- v0.41.0: Set Velocity renamed to Velocity, old saves follow.
            if n.kind == "Set Velocity" then n.kind = "Velocity" end
            -- v0.47.0: option strings went professional-case. Map the old
            -- ones so saved graphs keep their behavior instead of falling
            -- into default branches.
            if n.opts then
                for _, k in ipairs({ "Op", "Edge", "Mode",
                    "Arg1", "Arg2", "Arg3", "Arg4" }) do
                    local v = n.opts[k]
                    if OPMAP[v] then n.opts[k] = OPMAP[v] end
                end
            end
            local w = n.wires
            if w and w.text and not w.a then w.a = w.text; w.text = nil end
        end
        -- v0.22.0: config load swaps CF.Nodes contents; NIDX has to follow.
        reindex()
        table.clear(KEYC)
    end

    local function enc(v)
        local t = typeof(v)
        if t == "number" or t == "boolean" then return tostring(v) end
        if t == "string" then return string.format("%q", v) end
        if t == "Color3" then
            return string.format("Color3.new(%.5f,%.5f,%.5f)", v.R, v.G, v.B)
        end
        if t == "table" then
            local parts = {}
            for k, val in pairs(v) do
                if not (type(k) == "string" and k:sub(1, 1) == "_") then
                    local e = enc(val)
                    if e then
                        local ek = (type(k) == "number") and ("[" .. k .. "]")
                            or ("[" .. string.format("%q", k) .. "]")
                        parts[#parts + 1] = ek .. "=" .. e
                    end
                end
            end
            return "{" .. table.concat(parts, ",") .. "}"
        end
        return nil
    end

    local function graphText() return "KOFFEEGRAPH" .. enc(CF.Nodes) end

    -- v0.21.2: plenty of executors ship no clipboard API at all, so both directions
    -- fall back to a popup: copy shows the text to select by hand, paste takes it in.
    local function copyGraph()
        local set = setclipboard or toclipboard or (syn and syn.setclipboard)
        local txt = graphText()
        if set and pcall(set, txt) then return true, "copied" end
        if Shared.openTextPopup then
            Shared.openTextPopup("copy graph", txt,
                "", function() end, true)
            return true, "select all and copy"
        end
        return false, "no clipboard access"
    end

    -- Pasting runs loadstring on clipboard text, so the payload is scrubbed first:
    -- strip strings and the only call we allow, then reject anything with letters
    -- left. That leaves no way to smuggle a function call in through a shared graph.
    local function pasteGraph(txt)
        if type(txt) ~= "string" or txt == "" then return false, "nothing pasted" end
        local body = txt:match("KOFFEEGRAPH(.+)$")
        if not body then return false, "not a koffee graph" end
        local scrub = body:gsub("\\\"", ""):gsub('"[^"]*"', "")
        scrub = scrub:gsub("Color3%.new", ""):gsub("true", ""):gsub("false", ""):gsub("nil", "")
        if scrub:find("%a") then return false, "graph looks tampered with" end
        local ldr = loadstring or load
        local fn = ldr and ldr("return " .. body)
        if not fn then return false, "graph is malformed" end
        local ok2, data = pcall(fn)
        if not (ok2 and type(data) == "table") then return false, "graph is malformed" end
        local base = 0
        for _, n in ipairs(CF.Nodes) do if n.id > base then base = n.id end end
        local map = {}
        for _, n in ipairs(data) do
            if n.kind == "Set Velocity" then n.kind = "Velocity" end
            if type(n) == "table" and tonumber(n.id) and KINDS[n.kind] then
                base = base + 1
                map[n.id] = base
            end
        end
        local added = 0
        for _, n in ipairs(data) do
            if map[n.id] then
                local w = {}
                for k, ref in pairs(n.wires or {}) do w[k] = map[ref] end
                local o = {}
                for k, v in pairs(KINDS[n.kind].opts or {}) do o[k] = v end
                for k, v in pairs(n.opts or {}) do o[k] = v end
                table.insert(CF.Nodes, { id = map[n.id], kind = n.kind, opts = o, wires = w,
                    x = (tonumber(n.x) or 24) + 26, y = (tonumber(n.y) or 24) + 26 })
                added = added + 1
            end
        end
        reindex()
        return added > 0, added > 0 and ("pasted " .. added) or "nothing to paste"
    end

    local function addNode(kind, x, y)
        local K = KINDS[kind]
        if not K then return nil end
        local id = 1
        for _, n in ipairs(CF.Nodes) do if n.id >= id then id = n.id + 1 end end
        local o = {}
        for k, v in pairs(K.opts or {}) do o[k] = v end
        table.insert(CF.Nodes, { id = id, kind = kind, opts = o, wires = {},
                                 x = x or 24, y = y or 24 })
        reindex()
        return id
    end
    local function removeNode(id)
        for i, n in ipairs(CF.Nodes) do
            if n.id == id then table.remove(CF.Nodes, i); break end
        end
        for _, n in ipairs(CF.Nodes) do          -- drop wires pointing at it
            for k, ref in pairs(n.wires or {}) do
                if ref == id then n.wires[k] = nil end
            end
        end
        -- v0.22.0: NIDX would keep handing out the deleted node otherwise.
        reindex()
        KEYC[id] = nil
    end

    -- headers keyed off ORDER's own grouping, so the reference below is generated
    -- from the block registry and can never drift out of date
    local DOC_HEADS = {
        ["Target"]          = "Sources: these find things",
        ["For Each Player"] = "Repeating: runs everything after it once per player",
        ["Visible"]         = "Logic: these decide and reshape",
        ["Screen Position"] = "Position: these make things follow",
        ["Text"]            = "Drawing: these put things on your screen",
        ["3D Ring"]         = "In the World: real geometry, not screen overlay",
        ["Sound"]           = "Actions: these fire when something happens",
    }
    local DOC_BODY = {
        { h = "The Idea" },
        { p = "Blocks do one small job each and pass the answer along. On their own they do nothing. You connect them, and the connection is where the feature comes from." },
        { p = "A block that finds a player, a block that asks a question about them, a block that draws the answer. That is a feature you built without writing code." },
        { h = "Wiring" },
        { p = "Click the dot on the RIGHT of one block, then the dot on the LEFT of another. The source dot lights up while you are mid connection." },
        { p = "Click an input dot with nothing pending to unplug it. Drag a block by its header. Drag empty space to pan. Minus folds a block, X deletes it." },
        { p = "You can only connect things that fit. A block that produces a player will not plug into a slot that wants a colour, so a wire that looks refused is telling you something." },
        { h = "Three Rules Worth Knowing" },
        { p = "1. An input you do NOT wire falls back to that block's own setting. So a Text block on its own is just a label you place anywhere. Wire something in and it takes over." },
        { p = "2. Switch is the 'otherwise'. It holds both answers at once: text and colour for yes, text and colour for no: so you never need two blocks that can drift apart." },
        { p = "3. In a Text block, {a} {b} {c} get replaced by its three value inputs. So \"health is {a}\" with Info wired into Value A is one block, not two sitting next to each other." },
        { h = "Show When" },
        { p = "Every drawing block has a Show When input. Wire a yes/no into it and the block only appears when that is true. Leave it empty and it is always on." },
        { h = "Position" },
        { p = "Every drawing block has a Position input. Leave it empty and it sits where its X/Y sliders say. Wire Screen Position into it and it follows a part or a player through the world." },
        { h = "Sharing" },
        { p = "Copy Graph puts the whole thing on your clipboard as text. Paste adds it back, renumbering so it never collides with blocks you already have. That is how you send a setup to someone." },
    }

    -- worked examples, built as real graphs so they can be opened and taken apart
    local function wire(id, key, src) local n = nodeById(id); if n then n.wires[key] = src end end
    local function opt(id, k, v) local n = nodeById(id); if n then n.opts[k] = v end end

    local EXAMPLES = {
        {
            name = "Target Visible Readout",
            note = "Says VISIBLE in green or NOT VISIBLE in red, wherever your target is",
            build = function()
                local t = addNode("Target", 24, 24)
                local v = addNode("Visible", 24, 150)
                local s = addNode("Switch", 244, 150)
                local x = addNode("Text", 464, 150)
                opt(t, "Source", "Silent Aim Target")
                wire(v, "player", t)
                wire(s, "bool", v)
                wire(x, "a", s); wire(x, "color", s)
                opt(x, "Text", "{a}"); opt(x, "Y", 62); opt(x, "Size", 26)
            end,
        },
        {
            name = "Name + Health Over Every Enemy",
            note = "Per player, so this is a full custom ESP made of five blocks",
            build = function()
                local fe = addNode("For Each Player", 24, 24)
                local sp = addNode("Screen Position", 244, 24)
                local nm = addNode("Info", 244, 168)
                local hp = addNode("Info", 244, 300)
                local tx = addNode("Text", 500, 24)
                local br = addNode("Bar", 500, 210)
                opt(sp, "Anchor", "Above")
                wire(sp, "player", fe)
                opt(nm, "Field", "Name");       wire(nm, "player", fe)
                opt(hp, "Field", "Health 0-1"); wire(hp, "player", fe)
                wire(tx, "pos", sp); wire(tx, "a", nm)
                opt(tx, "Text", "{a}"); opt(tx, "Size", 14)
                local off = addNode("Offset", 500, 380)
                wire(off, "point", sp); opt(off, "Y", 16)
                wire(br, "pos", off); wire(br, "value", hp)
                opt(br, "W", 60); opt(br, "H", 5)
            end,
        },
        {
            name = "Label Over Your Target",
            note = "Follows the target and disappears the moment you are not on one",
            build = function()
                local t  = addNode("Target", 24, 24)
                local sp = addNode("Screen Position", 244, 24)
                local sw = addNode("Switch", 244, 190)
                local x  = addNode("Text", 500, 24)
                opt(sp, "Anchor", "Above")
                wire(sp, "player", t)
                -- Target's bool is "did it find anybody", which is what drives both
                -- the wording and whether the label exists at all
                wire(sw, "bool", t)
                opt(sw, "TrueText", "TARGET"); opt(sw, "FalseText", "")
                wire(x, "pos", sp); wire(x, "a", sw)
                wire(x, "color", sw); wire(x, "show", t)
                opt(x, "Text", "{a}"); opt(x, "Size", 15)
            end,
        },
        {
            name = "3D Scanning Ring On Your Target",
            note = "Real geometry in the world, eased, rides up and down the body",
            build = function()
                local t  = addNode("Target", 24, 24)
                local wp = addNode("World Position", 260, 24)
                local tm = addNode("Time", 24, 200)
                local mr = addNode("Map Range", 24, 310)
                local rg = addNode("3D Ring", 520, 24)
                wire(wp, "player", t)
                opt(wp, "Anchor", "Feet")
                -- Sine is already an ease: it slows at both ends of the travel where
                -- Ping-Pong would turn around hard
                opt(tm, "Mode", "Sine"); opt(tm, "Speed", 1.4)
                wire(mr, "number", tm)
                opt(mr, "InMin", -1); opt(mr, "InMax", 1)
                opt(mr, "OutMin", 0); opt(mr, "OutMax", 5.5)
                -- studs, so the ring stays on the body at any range with no maths
                wire(wp, "height", mr)
                wire(rg, "at", wp); wire(rg, "show", t)
                opt(rg, "Radius", 3.2); opt(rg, "Thickness", 0.15)
            end,
        },
    }

    local function docsModal(onBuilt)
        if not Shared.openModal then return end
        local vp = viewport()
        local m = Shared.openModal(math.min(600, vp.X - 60), math.min(560, vp.Y - 60))
        new("TextLabel", {
            Text = "Custom Features", FontFace = Theme.Fonts.Bold,
            TextSize = Theme.Text.Header, TextColor3 = Theme.Palette.Text,
            BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.new(0, 16, 0, 12), Size = UDim2.new(1, -32, 0, 18),
            ZIndex = 202, Parent = m.box,
        })
        local body = new("ScrollingFrame", {
            Position = UDim2.new(0, 10, 0, 38), Size = UDim2.new(1, -20, 1, -84),
            BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 4,
            ScrollBarImageColor3 = Theme.Palette.Border,
            CanvasSize = UDim2.new(0, 0, 0, 0),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollingDirection = Enum.ScrollingDirection.Y,
            ZIndex = 202, Parent = m.box,
        }, { new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 10) }),
             new("UIListLayout", { Padding = UDim.new(0, 5),
                 SortOrder = Enum.SortOrder.LayoutOrder }) })
        local order = 0
        local function head(t)
            order = order + 1
            new("TextLabel", {
                Text = t, FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Body,
                TextColor3 = Theme.Palette.Accent, BackgroundTransparency = 1,
                TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y,
                Size = UDim2.new(1, 0, 0, 16), TextXAlignment = Enum.TextXAlignment.Left,
                LayoutOrder = order, ZIndex = 203, Parent = body,
            }, { new("UIPadding", { PaddingTop = UDim.new(0, 8) }) })
        end
        local function para(t, muted)
            order = order + 1
            new("TextLabel", {
                Text = t, FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
                TextColor3 = muted and Theme.Palette.TextMuted or Theme.Palette.Text,
                BackgroundTransparency = 1, TextWrapped = true,
                AutomaticSize = Enum.AutomaticSize.Y, LineHeight = 1.25,
                Size = UDim2.new(1, 0, 0, 14), TextXAlignment = Enum.TextXAlignment.Left,
                LayoutOrder = order, ZIndex = 203, Parent = body,
            })
        end
        for _, e in ipairs(DOC_BODY) do
            if e.h then head(e.h) else para(e.p) end
        end
        head("Try One")
        for _, e in ipairs(EXAMPLES) do
            order = order + 1
            local b = new("TextButton", {
                Text = "Build: " .. e.name, AutoButtonColor = false,
                FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.TextMuted,
                BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
                BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 26),
                LayoutOrder = order, ZIndex = 203, Parent = body,
            }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
            b.MouseButton1Click:Connect(function()
                e.build()
                m.close()
                if onBuilt then onBuilt() end
            end)
            para(e.note, true)
        end
        para("These add to whatever is already on the canvas, they do not replace it", true)
        head("Every Block")
        for _, name in ipairs(ORDER) do
            if DOC_HEADS[name] then para(DOC_HEADS[name], true) end
            local K = KINDS[name]
            if K then para(name .. ": " .. (K.blurb or "")) end
        end
        local close = new("TextButton", {
            Text = "Close", AutoButtonColor = false, FontFace = Theme.Fonts.Medium,
            TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 1),
            Position = UDim2.new(1, -14, 1, -12), Size = UDim2.new(0, 88, 0, 26),
            ZIndex = 202, Parent = m.box,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        close.MouseButton1Click:Connect(m.close)
        return m
    end

    -- inline option rows: the inspector renders options directly, no popups
    local function textRow(parent, label, initial, onChange)
        local r = new("Frame", {
            Size = UDim2.new(1, 0, 0, 42), BackgroundTransparency = 1,
            ZIndex = 41, Parent = parent,
        })
        new("TextLabel", {
            Text = label, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 14), TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 42, Parent = r,
        })
        local box = new("TextBox", {
            Text = tostring(initial or ""), ClearTextOnFocus = false,
            FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Body,
            TextColor3 = Theme.Palette.Text, BackgroundColor3 = Theme.Palette.PanelElevated,
            BackgroundTransparency = 0.2, BorderSizePixel = 0,
            Position = UDim2.new(0, 0, 0, 17), Size = UDim2.new(1, 0, 0, 24),
            TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 42, Parent = r,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle),
            new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }) })
        box.FocusLost:Connect(function() onChange(box.Text) end)
    end
    local function labelRow(parent, text)
        new("TextLabel", {
            Text = text, FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1,
            TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y,
            Size = UDim2.new(1, 0, 0, 14), TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 41, Parent = parent,
        })
    end
    -- v0.23.0: section header for the inspector. A flat slider stack is why Corner
    -- Radius and Inside Group went unfound: grouped rows make them scannable.
    local function sectionRow(parent, text)
        local f = new("Frame", {
            BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 20),
            ZIndex = 41, Parent = parent,
        })
        new("Frame", {
            BackgroundColor3 = Theme.Palette.BorderSubtle, BorderSizePixel = 0,
            Position = UDim2.new(0, 0, 0, 3), Size = UDim2.new(1, 0, 0, 1),
            ZIndex = 41, Parent = f,
        })
        new("TextLabel", {
            Text = text, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1,
            Position = UDim2.new(0, 0, 0, 6), Size = UDim2.new(1, 0, 0, 14),
            TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 42, Parent = f,
        })
        return f
    end
    local function buttonRow(parent, text, onClick)
        local b = new("TextButton", {
            Text = text, AutoButtonColor = false, FontFace = Theme.Fonts.Medium,
            TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 24), ZIndex = 41, Parent = parent,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        b.MouseEnter:Connect(function()
            tween(b, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Text })
        end)
        b.MouseLeave:Connect(function()
            tween(b, Theme.Animation.Fast, { TextColor3 = Theme.Palette.TextMuted })
        end)
        b.MouseButton1Click:Connect(onClick)
        return b
    end
    local function swatchRow(parent, label, initial, onChange)
        local r = new("Frame", {
            Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1,
            ZIndex = 41, Parent = parent,
        })
        new("TextLabel", {
            Text = label, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Body,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1,
            Size = UDim2.new(1, -22, 1, 0), TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 42, Parent = r,
        })
        attachSingleSwatch(r, initial, onChange)
    end

    -- analytic node geometry: port centres never wait on a layout pass
    local NODE_W, HEAD_H, ROW_H, WIRE_SEG = 172, 24, 20, 12
    local TOOL_H, INSP_W, CANVAS_W, CANVAS_H = 90, 202, 2600, 1800
    local function nodeH(K, node)
        if node and node.fold then return HEAD_H + 4 end
        return HEAD_H + math.max(#K.ins, 1) * ROW_H + 6
    end
    local function portY(node, i)
        if node.fold then return HEAD_H * 0.5 end
        return HEAD_H + (i - 0.5) * ROW_H
    end
    local function bez(x1, y1, ax, ay, bx, by, x2, y2, t)
        local u = 1 - t
        local a, b, c, d = u * u * u, 3 * u * u * t, 3 * u * t * t, t * t * t
        return a * x1 + b * ax + c * bx + d * x2, a * y1 + b * ay + c * by + d * y2
    end
    local function toolBtn(parent, text, width, order, onClick, h)
        local b = new("TextButton", {
            Text = text, AutoButtonColor = false,
            FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextMuted,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, Size = UDim2.new(0, width, 0, h or 24),
            LayoutOrder = order, ZIndex = 36, Parent = parent,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        b.MouseEnter:Connect(function()
            tween(b, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Text })
        end)
        b.MouseLeave:Connect(function()
            tween(b, Theme.Animation.Fast, { TextColor3 = Theme.Palette.TextMuted })
        end)
        b.MouseButton1Click:Connect(onClick)
        popFx(b)   -- v0.48.3: toolbar buttons squash on press like the rest
        Koffee.attachBtnHover(b, 0, 0.2)
        return b
    end

    -- one implementation, used both inline in the tab and inside the expanded
    -- modal. `extra` puts a single button at the toolbar's right edge.
    local function makeEditor(parent, connList, extra)
        local canvas = new("ScrollingFrame", {
            Position = UDim2.new(0, 6, 0, TOOL_H),
            Size = UDim2.new(1, -(INSP_W + 22), 1, -(TOOL_H + 26)),
            BackgroundTransparency = 1, BorderSizePixel = 0,
            CanvasSize = UDim2.new(0, CANVAS_W, 0, CANVAS_H),
            ScrollingDirection = Enum.ScrollingDirection.XY,
            ScrollBarThickness = 6, ScrollBarImageColor3 = Theme.Palette.Border,
            ClipsDescendants = true, Active = true, ZIndex = 34, Parent = parent,
        })
        local wireLayer = new("Frame", {
            Size = UDim2.new(0, CANVAS_W, 0, CANVAS_H), BackgroundTransparency = 1,
            ZIndex = 34, Parent = canvas,
        })
        local hint = new("TextLabel", {
            Text = "", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
            Position = UDim2.new(0, 8, 1, -17), Size = UDim2.new(1, -(INSP_W + 20), 0, 14),
            TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 39, Parent = parent,
        })
        local insp = new("ScrollingFrame", {
            AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, TOOL_H),
            Size = UDim2.new(0, INSP_W, 1, -(TOOL_H + 26)),
            BackgroundColor3 = Theme.Palette.Panel, BackgroundTransparency = 0.02,
            BorderSizePixel = 0, ScrollBarThickness = 4,
            ScrollBarImageColor3 = Theme.Palette.Border,
            CanvasSize = UDim2.new(0, 0, 0, 0),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollingDirection = Enum.ScrollingDirection.Y,
            ZIndex = 40, Parent = parent,
        }, { corner(6), stroke(Theme.Palette.Border),
            new("UIPadding", { PaddingTop = UDim.new(0, 10), PaddingBottom = UDim.new(0, 10),
                PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10) }),
            new("UIListLayout", { Padding = UDim.new(0, 6),
                SortOrder = Enum.SortOrder.LayoutOrder }) })

        local sel, pending, dragId = nil, nil, nil
        local note, noteAt = nil, 0
        local panning, lastMX, lastMY = false, 0, 0
        local nodeFrames, wirePool = {}, {}
        local rebuildAll
        -- v0.48.0: remembers which node ids already had a frame so only
        -- genuinely new blocks pop in (add / paste) instead of every rebuild.
        local nodeSeenIds = {}

        local function inspApi(p)
            local a = {}
            function a:slider(l, mn, mx, i, pr, cb) slider(p, l, mn, mx, i, pr, cb) end
            function a:toggle(l, i, cb) configCheckbox(p, l, i, cb) end
            function a:dropdown(l, o, i, cb) dropdown(p, l, o, i, cb) end
            function a:text(l, i, cb) textRow(p, l, i, cb) end
            function a:swatch(l, i, cb) swatchRow(p, l, i, cb) end
            function a:label(t) labelRow(p, t) end
            function a:section(t) sectionRow(p, t) end
            function a:button(t, fn) buttonRow(p, t, function() fn(rebuildAll) end) end
            return a
        end

        local function buildInspector()
            for _, c in ipairs(insp:GetChildren()) do
                if c:IsA("GuiObject") then c:Destroy() end
            end
            local node = sel and nodeById(sel)
            if not (node and KINDS[node.kind]) then
                new("TextLabel", {
                    Text = "Click a block to edit it", FontFace = Theme.Fonts.Regular,
                    TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextFaint,
                    BackgroundTransparency = 1, TextWrapped = true,
                    Size = UDim2.new(1, 0, 0, 30), TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = 41, Parent = insp,
                })
                return
            end
            local K = KINDS[node.kind]
            new("TextLabel", {
                Text = node.kind .. " #" .. node.id, FontFace = Theme.Fonts.Bold,
                TextSize = Theme.Text.Header, TextColor3 = Theme.Palette.Text,
                BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 18),
                TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 41, Parent = insp,
            })
            new("TextLabel", {
                Text = K.blurb, FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
                TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y,
                Size = UDim2.new(1, 0, 0, 14), TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 41, Parent = insp,
            })
            if K.ui then K.ui(inspApi(insp), node.opts) end
        end

        local function seg(i)
            local f = wirePool[i]
            if not f then
                f = new("Frame", {
                    BackgroundColor3 = Theme.Palette.Accent, BorderSizePixel = 0,
                    AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 34, Parent = wireLayer,
                })
                wirePool[i] = f
            end
            return f
        end
        local function redrawWires()
            local n = 0
            for _, node in ipairs(CF.Nodes) do
                local K = KINDS[node.kind]
                if K then
                    for i, slot in ipairs(K.ins) do
                        local src = node.wires and node.wires[slot.key]
                        src = src and nodeById(src)
                        if src and KINDS[src.kind] then
                            local x2, y2 = node.x, node.y + portY(node, i)
                            local x1, y1 = src.x + NODE_W, src.y + portY(src, 1)
                            local off = math.max(40, math.abs(x2 - x1) * 0.5)
                            local px, py = x1, y1
                            for s = 1, WIRE_SEG do
                                local qx, qy = bez(x1, y1, x1 + off, y1, x2 - off, y2, x2, y2,
                                                   s / WIRE_SEG)
                                n = n + 1
                                local f = seg(n)
                                local dx, dy = qx - px, qy - py
                                f.Size = UDim2.new(0, math.sqrt(dx * dx + dy * dy) + 1.5, 0, 2)
                                f.Position = UDim2.new(0, (px + qx) * 0.5, 0, (py + qy) * 0.5)
                                f.Rotation = math.deg(math.atan2(dy, dx))
                                f.Visible = true
                                px, py = qx, qy
                            end
                        end
                    end
                end
            end
            for i = n + 1, #wirePool do wirePool[i].Visible = false end
        end

        local function buildNodes()
            for _, f in pairs(nodeFrames) do f:Destroy() end
            nodeFrames = {}
            for _, node in ipairs(CF.Nodes) do
                local K = KINDS[node.kind]
                if K then
                    node.x, node.y = node.x or 24, node.y or 24
                    local picked = (sel == node.id)
                    local f = new("Frame", {
                        Position = UDim2.new(0, node.x, 0, node.y),
                        Size = UDim2.new(0, NODE_W, 0, nodeH(K, node)),
                        BackgroundColor3 = Theme.Palette.Panel, BackgroundTransparency = 0.02,
                        BorderSizePixel = 0, Active = true, ZIndex = 35, Parent = canvas,
                    }, { corner(6),
                        stroke(picked and Theme.Palette.Accent or Theme.Palette.Border) })
                    nodeFrames[node.id] = f
                    -- v0.48.0: new blocks pop onto the canvas; Lists off (or
                    -- master off, inside popIn) shows them at rest instead.
                    if Koffee.Anim.spot("AnimLists") and not nodeSeenIds[node.id] then
                        Koffee.popIn(f)
                    end

                    local head = new("TextButton", {
                        Text = "  " .. (node.kind == "Note"
                            and (node.opts.Text ~= "" and node.opts.Text or "Note")
                            or node.kind),
                        AutoButtonColor = false,
                        FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
                        TextColor3 = picked and Theme.Palette.Accent or Theme.Palette.Text,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        BackgroundColor3 = Theme.Palette.PanelElevated,
                        BackgroundTransparency = 0.15, BorderSizePixel = 0,
                        Size = UDim2.new(1, 0, 0, HEAD_H), ZIndex = 36, Parent = f,
                    }, { corner(6) })
                    local del = new("TextButton", {
                        Text = "X", AutoButtonColor = false, FontFace = Theme.Fonts.Bold,
                        TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextFaint,
                        BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, -5, 0.5, 0), Size = UDim2.new(0, 16, 0, 16),
                        ZIndex = 37, Parent = head,
                    })
                    local fold = new("TextButton", {
                        Text = node.fold and "+" or "-", AutoButtonColor = false,
                        FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
                        TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1,
                        AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, -21, 0.5, 0), Size = UDim2.new(0, 16, 0, 16),
                        ZIndex = 37, Parent = head,
                    })
                    fold.MouseButton1Click:Connect(function()
                        node.fold = not node.fold or nil
                        rebuildAll()
                    end)
                    del.MouseButton1Click:Connect(function()
                        removeNode(node.id)
                        if sel == node.id then sel = nil end
                        if pending == node.id then pending = nil end
                        rebuildAll()
                    end)
                    head.MouseButton1Click:Connect(function() sel = node.id; rebuildAll() end)
                    head.InputBegan:Connect(function(inp)
                        if inp.UserInputType == Enum.UserInputType.MouseButton1 then
                            -- delta dragging: immune to canvas scroll offset entirely
                            local m = UserInputService:GetMouseLocation()
                            dragId, lastMX, lastMY = node.id, m.X, m.Y
                        end
                    end)

                    for i, slot in ipairs(K.ins) do
                        local y = HEAD_H + (i - 1) * ROW_H
                        if not node.fold then
                        new("TextLabel", {
                            Text = slot.label, FontFace = Theme.Fonts.Regular,
                            TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
                            BackgroundTransparency = 1, Position = UDim2.new(0, 13, 0, y),
                            Size = UDim2.new(1, -26, 0, ROW_H),
                            TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 36, Parent = f,
                        })
                        end
                        local lit = node.wires and node.wires[slot.key] ~= nil
                        local p = new("TextButton", {
                            Text = "", AutoButtonColor = false, BorderSizePixel = 0,
                            BackgroundColor3 = lit and Theme.Palette.Accent
                                or Theme.Palette.PanelElevated,
                            AnchorPoint = Vector2.new(0.5, 0.5),
                            Position = UDim2.new(0, 0, 0, portY(node, i)),
                            Size = UDim2.new(0, node.fold and 7 or 11, 0, node.fold and 7 or 11),
                            ZIndex = 38, Parent = f,
                        }, { pillCorner(), stroke(Theme.Palette.Border) })
                        p.MouseButton1Click:Connect(function()
                            node.wires = node.wires or {}
                            if pending then
                                local src = nodeById(pending)
                                local SK = src and KINDS[src.kind]
                                if src and SK and SK.outs[slot.type] and src.id ~= node.id then
                                    node.wires[slot.key] = pending
                                end
                                pending = nil
                            else
                                node.wires[slot.key] = nil   -- click a wired dot to unplug
                            end
                            rebuildAll()
                        end)
                    end

                    if next(K.outs) then
                        local op = new("TextButton", {
                            Text = "", AutoButtonColor = false, BorderSizePixel = 0,
                            BackgroundColor3 = (pending == node.id) and Theme.Palette.Accent
                                or Theme.Palette.PanelElevated,
                            AnchorPoint = Vector2.new(0.5, 0.5),
                            Position = UDim2.new(1, 0, 0, portY(node, 1)),
                            Size = UDim2.new(0, 11, 0, 11), ZIndex = 38, Parent = f,
                        }, { pillCorner(), stroke(Theme.Palette.Border) })
                        op.MouseButton1Click:Connect(function()
                            pending = (pending == node.id) and nil or node.id
                            sel = node.id
                            rebuildAll()
                        end)
                    end
                end
            end
            -- v0.48.0: everything alive counts as seen, so the next rebuild
            -- only pops brand-new ids (deleted ids drop out, and pop again
            -- if ever re-added: correct).
            local fresh = {}
            for _, node in ipairs(CF.Nodes) do fresh[node.id] = true end
            nodeSeenIds = fresh
        end

        -- v0.26.1: Design Mode selects the node whose widget you clicked, so the
        -- inspector follows the screen. Last editor built wins, which is the open one.
        Koffee._cfSelect = function(id)
            sel = id
            if rebuildAll then rebuildAll() end
        end
        rebuildAll = function()
            migrate()
            buildNodes()
            redrawWires()
            buildInspector()
            if pending then
                local s = nodeById(pending)
                hint.Text = "Connecting from " .. (s and s.kind or "?")
                    .. ": click a matching input dot"
            elseif note and os.clock() - noteAt < 3 then
                hint.Text = note
            elseif #CF.Nodes == 0 then
                hint.Text = "Add a block above to start"
            else
                hint.Text = "Drag headers to move: output dot, then input dot, to connect"
            end
        end

        local function freeSpot()
            for row = 0, 24 do
                for col = 0, 7 do
                    local x, y = 24 + col * 210, 24 + row * 104
                    local taken = false
                    for _, n in ipairs(CF.Nodes) do
                        if n.x and math.abs(n.x - x) < 8 and math.abs(n.y - y) < 8 then
                            taken = true; break
                        end
                    end
                    if not taken then return x, y end
                end
            end
            return 24, 24
        end

        local function barAt(y, h)
            return new("Frame", {
                Position = UDim2.new(0, 6, 0, y), Size = UDim2.new(1, -12, 0, h or 24),
                BackgroundTransparency = 1, ZIndex = 35, Parent = parent,
            }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
                Padding = UDim.new(0, 5), VerticalAlignment = Enum.VerticalAlignment.Center,
                SortOrder = Enum.SortOrder.LayoutOrder }) })
        end
        local bar, bar2 = barAt(8, 48), barAt(60)
        -- v0.37.0: bottom-align the top row so "add block" lines up with the dropdown's
        -- box instead of centering against the taller dropdown (it read as "too high").
        local barLayout = bar:FindFirstChildOfClass("UIListLayout")
        if barLayout then barLayout.VerticalAlignment = Enum.VerticalAlignment.Bottom end
        local function say(msg) note, noteAt = msg, os.clock() end
        local pick = ORDER[1]
        local ddw = new("Frame", {
            Size = UDim2.new(0, 216, 0, 48), BackgroundTransparency = 1,
            LayoutOrder = 1, ZIndex = 36, Parent = bar,
        })
        -- v0.42.0: filterable block picker. Typing rebuilds the dropdown
        -- from matching ORDER names (plain substring); empty = full list.
        local searchBox = new("TextBox", {
            Size = UDim2.new(0, 110, 0, 26),
            Text = "", PlaceholderText = "Search",
            ClearTextOnFocus = false, FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Tiny,
            TextColor3 = Theme.Palette.Text, PlaceholderColor3 = Theme.Palette.TextFaint,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, LayoutOrder = 0, ZIndex = 36, Parent = bar,
        }, { corner(4), stroke(Theme.Palette.BorderSubtle),
            new("UIPadding", { PaddingLeft = UDim.new(0, 24) }) })
        local searchIcon = Koffee.lucideIcon(searchBox, "search", 12, Theme.Palette.TextFaint, 37)
        if searchIcon then
            searchIcon.AnchorPoint = Vector2.new(0, 0.5)
            searchIcon.Position = UDim2.new(0, 7, 0.5, 0)
        end
        local pickDD = nil
        local function rebuildPick()
            local q = (searchBox.Text or ""):lower()
            local opts = {}
            for _, n in ipairs(ORDER) do
                if q == "" or n:lower():find(q, 1, true) then opts[#opts + 1] = n end
            end
            if #opts == 0 then opts = { "(no match)" } end
            local keep = false
            for _, n in ipairs(opts) do if n == pick then keep = true break end end
            pick = keep and pick or opts[1]
            if pickDD then pickDD.destroy() end
            pickDD = dropdown(ddw, "Block", opts, pick, function(v) pick = v end)
        end
        searchBox:GetPropertyChangedSignal("Text"):Connect(rebuildPick)
        rebuildPick()
        toolBtn(bar, "Add Block", 110, 2, function()
            if not KINDS[pick] then say("Nothing matches"); return end
            local x, y = freeSpot()
            sel = addNode(pick, x, y)
            rebuildAll()
        end, 30)   -- v0.48.3: the primary action runs larger than its neighbours
        toolBtn(bar2, "Duplicate", 78, 1, function()
            local n = sel and nodeById(sel)
            if not n then say("Select a block first"); rebuildAll(); return end
            local id = 1
            for _, m in ipairs(CF.Nodes) do if m.id >= id then id = m.id + 1 end end
            local o, w = {}, {}
            for k, v in pairs(n.opts or {}) do o[k] = v end
            for k, v in pairs(n.wires or {}) do w[k] = v end
            table.insert(CF.Nodes, { id = id, kind = n.kind, opts = o, wires = w,
                x = (n.x or 24) + 22, y = (n.y or 24) + 22 })
            sel = id
            rebuildAll()
        end)
        toolBtn(bar2, "Copy Graph", 84, 2, function()
            local _, msg = copyGraph(); say(msg); rebuildAll()
        end)
        toolBtn(bar2, "Paste", 60, 3, function()
            -- straight to the popup: reading the clipboard needs an API most
            -- executors do not have, and a silent "no clipboard access" reads as broken
            if not Shared.openTextPopup then say("No text input"); return end
            Shared.openTextPopup("paste graph", "", "paste the KOFFEEGRAPH text here",
                function(txt)
                    local _, msg = pasteGraph(txt)
                    say(msg)
                    rebuildAll()
                end, true)
        end)
        toolBtn(bar2, "Docs", 56, 5, function() docsModal(rebuildAll) end)
        toolBtn(bar2, "Clear", 58, 4, function()
            for i = #CF.Nodes, 1, -1 do CF.Nodes[i] = nil end
            sel, pending = nil, nil
            say("Cleared"); rebuildAll()
        end)
        if extra then toolBtn(bar2, extra.text, 74, 99, extra.fn) end

        canvas.InputBegan:Connect(function(inp)
            if inp.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
            local m = UserInputService:GetMouseLocation()
            panning, lastMX, lastMY = true, m.X, m.Y
            if pending or sel then pending, sel = nil, nil; rebuildAll() end
        end)
        connList[#connList + 1] = UserInputService.InputChanged:Connect(function(inp)
            if inp.UserInputType ~= Enum.UserInputType.MouseMovement then return end
            if not canvas.Parent then return end
            local m = UserInputService:GetMouseLocation()
            local dx, dy = m.X - lastMX, m.Y - lastMY
            lastMX, lastMY = m.X, m.Y
            if dragId then
                local node = nodeById(dragId)
                if node then
                    node.x, node.y = math.max(0, node.x + dx), math.max(0, node.y + dy)
                    local f = nodeFrames[dragId]
                    if f then f.Position = UDim2.new(0, node.x, 0, node.y) end
                    redrawWires()
                end
            elseif panning then
                local c = canvas.CanvasPosition
                canvas.CanvasPosition = Vector2.new(c.X - dx, c.Y - dy)
            end
        end)
        connList[#connList + 1] = UserInputService.InputEnded:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1 then
                dragId, panning = nil, false
            end
        end)

        rebuildAll()
        return rebuildAll
    end

    local tabConns = {}

    -- v0.37.0 BUFFER LAB (paste + inspect + schema): grab a buffer from an external
    -- spy (Turtle Spy / Cobalt), paste it, decode it, then label its fields into a
    -- reusable schema. Stage 3 (build + fire from a schema) is still to come.
    local function buildBufferLab(parent)
        local RTYPES = { "u8", "i8", "u16", "i16", "u32", "i32", "f32", "f64", "string" }
        local SDIR = "Koffee/buffers"
        local HttpService = game:GetService("HttpService")
        local curBytes = ""
        local fields = {}   -- { { off, type, name } }
        local addType = "f32"
        local refreshFields   -- fwd decl (used by the add-field button below)
        local lastGuesses = {}   -- auto-detected fields, materialized by "auto fields"
        local saneMax = 50000    -- v0.39.0: customizable "plausible float" ceiling for auto-detect

        local function mkBtn(p, text, w, order, fn)
            local b = new("TextButton", {
                Text = text, AutoButtonColor = false, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
                Size = UDim2.fromOffset(w, 24), TextColor3 = Theme.Palette.TextMuted,
                LayoutOrder = order, ZIndex = 36, Parent = p,
            }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
            b.MouseEnter:Connect(function() tween(b, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Text }) end)
            b.MouseLeave:Connect(function() tween(b, Theme.Animation.Fast, { TextColor3 = Theme.Palette.TextMuted }) end)
            b.MouseButton1Click:Connect(fn)
            Koffee.attachBtnHover(b, 0, 0.2)   -- v0.48.0: background eases in with the text
            return b
        end
        local function inputBox(p, place, w, order)
            return new("TextBox", {
                Text = "", PlaceholderText = place, ClearTextOnFocus = false,
                FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.Text, PlaceholderColor3 = Theme.Palette.TextFaint,
                BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
                Size = w, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = order, ZIndex = 36, Parent = p,
            }, { corner(5), stroke(Theme.Palette.BorderSubtle),
                new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }) })
        end

        local function unescape(s)
            s = s:gsub("\\x(%x%x)", function(h) return string.char(tonumber(h, 16)) end)
            s = s:gsub("\\(%d%d?%d?)", function(d) local n = tonumber(d); return (n and n < 256) and string.char(n) or "" end)
            s = s:gsub("\\n", "\n"):gsub("\\t", "\t"):gsub("\\r", "\r")
            s = s:gsub('\\"', '"'):gsub("\\\\", "\\")
            return s
        end
        local function parsePaste(txt)
            if not txt or txt == "" then return nil, "nothing pasted" end
            local lit = txt:match('fromstring%s*%(%s*"(.-)"') or txt:match("fromstring%s*%(%s*'(.-)'")
            if lit then return unescape(lit) end
            local stripped = txt:gsub("0[xX]", ""):gsub("[%s,]", "")
            if #stripped >= 2 and stripped:match("^%x+$") then
                if #stripped % 2 ~= 0 then stripped = stripped:sub(1, #stripped - 1) end
                local out = {}
                for h in stripped:gmatch("..") do out[#out + 1] = string.char(tonumber(h, 16)) end
                return table.concat(out)
            end
            return txt
        end
        local function readField(off, ty)
            if curBytes == "" then return nil end
            local ok, b = pcall(buffer.fromstring, curBytes)
            if not ok then return nil end
            local n = buffer.len(b)
            local ok2, v = pcall(function()
                if ty == "u8" then return buffer.readu8(b, off) end
                if ty == "i8" then return buffer.readi8(b, off) end
                if ty == "u16" then return buffer.readu16(b, off) end
                if ty == "i16" then return buffer.readi16(b, off) end
                if ty == "u32" then return buffer.readu32(b, off) end
                if ty == "i32" then return buffer.readi32(b, off) end
                if ty == "f32" then return buffer.readf32(b, off) end
                if ty == "f64" then return buffer.readf64(b, off) end
                if ty == "string" then return buffer.readstring(b, off, math.max(0, math.min(16, n - off))) end
            end)
            return ok2 and v or nil
        end

        -- schema files (guarded)
        local function filesOk() return writefile and readfile and isfile and listfiles end
        local function ensureDir()
            if isfolder and makefolder then
                if not isfolder("Koffee") then pcall(makefolder, "Koffee") end
                if not isfolder(SDIR) then pcall(makefolder, SDIR) end
            end
        end
        local function listSchemas()
            local out = {}
            if not filesOk() then return out end
            ensureDir()
            local ok, files = pcall(listfiles, SDIR)
            if ok and type(files) == "table" then
                for _, p in ipairs(files) do
                    local nm = tostring(p):match("([^/\\]+)%.json$")
                    if nm then out[#out + 1] = nm end
                end
            end
            table.sort(out)
            return out
        end

        -- === paste card ===
        local card = panel(parent, "Buffer Lab")
        labelRow(card, "grab a remote's buffer from Turtle Spy / Cobalt and paste it below")
        labelRow(card, "hex, a buffer.fromstring(\"...\") snippet, or raw bytes")
        local box = new("TextBox", {
            Text = "", PlaceholderText = "Paste buffer bytes / fromstring code / hex...",
            ClearTextOnFocus = false, MultiLine = true, TextWrapped = true,
            FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, PlaceholderColor3 = Theme.Palette.TextFaint,
            BackgroundColor3 = Theme.Palette.Background, BackgroundTransparency = 0.15,
            Size = UDim2.new(1, 0, 0, 80), TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Top, LayoutOrder = 20, ZIndex = 36, Parent = card,
        }, { corner(6), stroke(Theme.Palette.BorderSubtle),
            new("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 6),
                PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }) })
        local pRow = new("Frame", {
            Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1, LayoutOrder = 21, ZIndex = 36, Parent = card,
        }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6),
            VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
        -- v0.39.0: customizable sanity ceiling: floats bigger than this are treated
        -- as garbage by auto-detect (raise it for big-coordinate maps, lower to be strict).
        local saneBox = inputBox(card, "auto-detect max |value| (default 50000)", UDim2.new(1, 0, 0, 24), 22)

        -- === inspector card ===
        local icard = panel(parent, "Inspector")
        local header = new("TextLabel", {
            Text = "Paste a buffer and hit Decode", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, 0, 0, 16), TextTruncate = Enum.TextTruncate.AtEnd, LayoutOrder = 1, ZIndex = 36, Parent = icard,
        })
        local ibody = new("ScrollingFrame", {
            Size = UDim2.new(1, 0, 0, 210), BackgroundColor3 = Theme.Palette.Background, BackgroundTransparency = 0.2,
            ScrollBarThickness = 4, ScrollBarImageColor3 = Theme.Palette.TextFaint,
            CanvasSize = UDim2.new(0, 0, 0, 0), AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollingDirection = Enum.ScrollingDirection.Y, LayoutOrder = 2, ZIndex = 35, Parent = icard,
        }, { corner(6), stroke(Theme.Palette.BorderSubtle),
            new("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 6),
                PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }),
            new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical, Padding = UDim.new(0, 6),
                SortOrder = Enum.SortOrder.LayoutOrder }) })
        local dump = new("TextLabel", {
            Text = "", FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
            BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
            AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.fromScale(1, 0), LayoutOrder = 1, ZIndex = 36, Parent = ibody,
        })
        local guess = new("TextLabel", {
            Text = "", FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.Accent,
            BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
            AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.fromScale(1, 0), LayoutOrder = 2, ZIndex = 36, Parent = ibody,
        })

        local function inspect()
            local blen = #curBytes
            header.Text = (blen > 0) and (blen .. " bytes") or "Paste a buffer and hit Decode"
            local lines, shown = {}, math.min(blen, 256)
            for off = 0, shown - 1, 16 do
                local parts = {}
                for j = 0, 15 do
                    local k = off + j
                    if k < shown then parts[#parts + 1] = ("%02X"):format(curBytes:byte(k + 1)) end
                end
                lines[#lines + 1] = ("%04X  %s"):format(off, table.concat(parts, " "))
            end
            if blen > shown then lines[#lines + 1] = ("... (%d more bytes)"):format(blen - shown) end
            dump.Text = table.concat(lines, "\n")
            -- auto-detect: sane f32s (finite, not garbage-huge), Vector3 triplets first.
            -- This is the sanity check: 9e19 as an X, 0 as Y is NOT a position, so
            -- absurd floats are rejected instead of being suggested as fields.
            local guesses = {}
            lastGuesses = {}
            local ok, b = pcall(buffer.fromstring, curBytes)
            if ok and blen > 0 then
                local n = buffer.len(b)
                local function rf(o) local okk, v = pcall(buffer.readf32, b, o); return okk and v or nil end
                local function sane(f)
                    return f ~= nil and f == f and math.abs(f) ~= math.huge
                        and (f == 0 or (math.abs(f) >= 1e-3 and math.abs(f) < saneMax))
                end
                local off = 0
                while off <= n - 4 and #guesses < 40 do
                    if off <= n - 12 then
                        local x, y, z = rf(off), rf(off + 4), rf(off + 8)
                        if sane(x) and sane(y) and sane(z) and not (x == 0 and y == 0 and z == 0) then
                            guesses[#guesses + 1] = ("off %-4d  vec3? (%.1f, %.1f, %.1f)"):format(off, x, y, z)
                            lastGuesses[#lastGuesses + 1] = { off = off, type = "f32", name = "x@" .. off }
                            lastGuesses[#lastGuesses + 1] = { off = off + 4, type = "f32", name = "y@" .. off }
                            lastGuesses[#lastGuesses + 1] = { off = off + 8, type = "f32", name = "z@" .. off }
                            off = off + 12
                            continue
                        end
                    end
                    local x = rf(off)
                    if sane(x) and x ~= 0 then
                        guesses[#guesses + 1] = ("off %-4d  f32 = %.3f"):format(off, x)
                        lastGuesses[#lastGuesses + 1] = { off = off, type = "f32", name = "f32@" .. off }
                    else
                        local oku, u = pcall(buffer.readu32, b, off)
                        if oku and u > 0 and u < 100000 then
                            guesses[#guesses + 1] = ("off %-4d  u32 = %d"):format(off, u)
                            lastGuesses[#lastGuesses + 1] = { off = off, type = "u32", name = "u32@" .. off }
                        end
                    end
                    off = off + 4
                end
            end
            guess.Text = (#guesses > 0) and ("auto-detected (guesses):\n" .. table.concat(guesses, "\n"))
                or "no obvious fields: add them by hand"
        end

        -- === fields / schema card (stage 2) ===
        local fcard = panel(parent, "Fields")
        labelRow(fcard, "label the bytes: an offset + type + name becomes a reusable schema")
        local offBox = inputBox(fcard, "offset (e.g. 4)", UDim2.new(1, 0, 0, 24), 10)
        offBox.LayoutOrder = 10
        local tHold = new("Frame", { Size = UDim2.new(1, 0, 0, 48), BackgroundTransparency = 1, LayoutOrder = 11, ZIndex = 36, Parent = fcard })
            dropdown(tHold, "Type", RTYPES, addType, function(v) addType = v end)
        local nameBox = inputBox(fcard, "name (e.g. targetX)", UDim2.new(1, 0, 0, 24), 12)
        nameBox.LayoutOrder = 12
        mkBtn(fcard, "Add Field", 84, 13, function()
            local off = tonumber((offBox.Text or ""):match("%d+"))
            if not off then return end
            local nm = (nameBox.Text ~= "" and nameBox.Text) or (addType .. "@" .. off)
            fields[#fields + 1] = { off = off, type = addType, name = nm }
            offBox.Text, nameBox.Text = "", ""
            refreshFields()
        end).LayoutOrder = 13

        local fieldList = new("Frame", {
            Size = UDim2.fromScale(1, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
            LayoutOrder = 20, ZIndex = 36, Parent = fcard,
        }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical, Padding = UDim.new(0, 3),
            SortOrder = Enum.SortOrder.LayoutOrder }) })
        local fieldRows = {}
        refreshFields = function()
            for _, r in ipairs(fieldRows) do pcall(function() r:Destroy() end) end
            table.clear(fieldRows)
            for i, fd in ipairs(fields) do
                local v = readField(fd.off, fd.type)
                local vs = (v == nil) and "?" or (type(v) == "number" and (fd.type == "f32" or fd.type == "f64") and ("%.3f"):format(v) or tostring(v))
                local rr = new("Frame", {
                    Size = UDim2.new(1, 0, 0, 20), BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.3,
                    LayoutOrder = i, ZIndex = 36, Parent = fieldList,
                }, { corner(4) })
                new("TextLabel", {
                    Text = ("%s   %s@%d = %s"):format(fd.name, fd.type, fd.off, vs),
                    FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.Text,
                    BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
                    Position = UDim2.fromOffset(8, 0), Size = UDim2.new(1, -34, 1, 0), ZIndex = 37, Parent = rr,
                })
                local xb = new("TextButton", {
                    Text = "X", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.Danger,
                    BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -6, 0.5, 0),
                    Size = UDim2.fromOffset(16, 16), ZIndex = 37, Parent = rr,
                })
                xb.MouseButton1Click:Connect(function() table.remove(fields, i); refreshFields() end)
                fieldRows[#fieldRows + 1] = rr
                -- v0.48.0: labeled rows cascade in like Mods rows do; Lists
                -- off (or master off, inside popIn) shows them at rest.
                if Koffee.Anim.spot("AnimLists") then
                    local sc, target, d = uScaleOf(rr), rr, math.min(i * 0.02, 0.3)
                    sc.Scale = 0.96
                    task.delay(d, function()
                        if target.Parent then
                            tween(sc, Theme.Animation.Fast, { Scale = 1 })
                        end
                    end)
                end
            end
        end

        -- schema save / load
        local schemaBox = inputBox(fcard, "schema name...", UDim2.new(1, -160, 0, 24), 30)
        local sRow = new("Frame", {
            Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1, LayoutOrder = 33, ZIndex = 36, Parent = fcard,
        }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6),
            VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
        local loadHold = new("Frame", { Size = UDim2.new(1, 0, 0, 48), BackgroundTransparency = 1, LayoutOrder = 32, ZIndex = 36, Parent = fcard })
        local pickSchema, loadDd = (listSchemas()[1] or ""), nil
        local function rebuildLoadDd()
            if loadDd then pcall(loadDd.destroy) end
            local names = listSchemas()
            if #names == 0 then names = { "no schemas" } end
            loadDd = dropdown(loadHold, "Saved Schemas", names, pickSchema ~= "" and pickSchema or names[1],
                function(v) pickSchema = v end)
        end

        mkBtn(fcard, "Save Schema", 96, 31, function()
            local nm = (schemaBox.Text or ""):gsub("[^%w _%-]", ""):gsub("^%s+", ""):gsub("%s+$", "")
            if nm == "" or not filesOk() then return end
            ensureDir()
            -- v0.39.0: store the pasted bytes as a hex TEMPLATE too, so Build Buffer
            -- can start from this known-good buffer and patch only the labeled fields.
            local tmplHex = {}
            for i = 1, #curBytes do tmplHex[i] = ("%02x"):format(curBytes:byte(i)) end
            local ok = pcall(function()
                writefile(SDIR .. "/" .. nm .. ".json",
                    HttpService:JSONEncode({ fields = fields, template = table.concat(tmplHex) }))
            end)
            if ok then pickSchema = nm; rebuildLoadDd() end
        end).LayoutOrder = 31
        mkBtn(sRow, "Load", 60, 1, function()
            if not filesOk() or pickSchema == "" then return end
            local p = SDIR .. "/" .. pickSchema .. ".json"
            if not isfile(p) then return end
            local ok, txt = pcall(readfile, p)
            if not ok then return end
            local dok, data = pcall(function() return HttpService:JSONDecode(txt) end)
            if dok and type(data) == "table" then
                -- v0.39.0: new format is { fields, template }; old was a bare fields array.
                local flds = (type(data.fields) == "table") and data.fields or data
                fields = {}
                for _, fd in ipairs(flds) do
                    if type(fd) == "table" and fd.off and fd.type then
                        fields[#fields + 1] = { off = fd.off, type = fd.type, name = fd.name or (fd.type .. "@" .. fd.off) }
                    end
                end
                refreshFields()
            end
        end)
        mkBtn(sRow, "Delete", 66, 2, function()
            if not (filesOk() and delfile) or pickSchema == "" then return end
            local p = SDIR .. "/" .. pickSchema .. ".json"
            if isfile(p) then pcall(delfile, p) end
            pickSchema = ""
            rebuildLoadDd()
        end)

        -- decode / clear in the paste card
        mkBtn(pRow, "Decode", 84, 1, function()
            local bytes, err = parsePaste(box.Text)
            if not bytes then header.Text = err or "Nothing to decode"; return end
            saneMax = tonumber((saneBox.Text or ""):match("[%d%.]+")) or 50000
            curBytes = bytes
            inspect()
            refreshFields()
        end)
        mkBtn(pRow, "Auto Fields", 92, 2, function()
            if #lastGuesses == 0 then return end
            fields = {}
            for _, g in ipairs(lastGuesses) do fields[#fields + 1] = { off = g.off, type = g.type, name = g.name } end
            refreshFields()
        end)
        mkBtn(pRow, "Clear", 60, 3, function()
            box.Text = ""; curBytes = ""; inspect(); refreshFields()
        end)

        inspect()
        refreshFields()
        rebuildLoadDd()
    end

    addTab("Custom", function(root)
        for _, c in ipairs(tabConns) do pcall(function() c:Disconnect() end) end
        tabConns = {}

        -- v0.35.0: Features (node graph) + Buffers (Buffer Lab) as sub-tabs.
        local switchCard = panel(root)
        local subs = Shared.subTabs(switchCard, { "Features", "Buffers" })
        local feat, buffs = subs.Features, subs.Buffers

        local card = panel(feat, "Custom Features")
        configCheckbox(card, "Enabled", CF.Enabled, function(v) CF.Enabled = v end)
        -- v0.24.0: design-pixel scale. Auto tracks screen height off a 1080p base.
        dropdown(card, "UI Scale", SCALE_NAMES, CF.Scale, function(v) CF.Scale = v end)
        labelRow(card, "scales every custom widget together. Auto follows screen height")
        -- v0.25.0: not persisted: design mode is a session tool, never a saved state
        configCheckbox(card, "Design Mode", false, function(v) Koffee._designMode(v) end)
        labelRow(card, "closes the window. click a widget to select, drag to move")
        labelRow(card, "corner dots resize, green dot rotates, arrows nudge, esc deselects")

        local frame = new("Frame", {
            Size = UDim2.new(1, 0, 0, 452), BackgroundColor3 = Theme.Palette.Background,
            BackgroundTransparency = 0.2, BorderSizePixel = 0, ClipsDescendants = true,
            Active = true, LayoutOrder = 50, ZIndex = 33, Parent = feat,
        }, { corner(6), stroke(Theme.Palette.BorderSubtle) })

        local refresh
            refresh = makeEditor(frame, tabConns, { text = "Expand", fn = function()
            local vp = viewport()
            if not Shared.openModal then return end
            local m = Shared.openModal(math.max(620, vp.X - 80), math.max(460, vp.Y - 80))
            local mConns = {}
            makeEditor(m.box, mConns, { text = "Close", fn = function()
                for _, c in ipairs(mConns) do pcall(function() c:Disconnect() end) end
                m.close()
                refresh()          -- pick up whatever was edited in the big view
            end })
        end })

        buildBufferLab(buffs)
    end)
end)()

addTab("Configs", function(root)
    local CIO = Koffee.Config

    -- v0.0.47: pill button whose resting colour can flip at runtime (the `auto`
    -- button toggles accent/muted). Base colour is stored as an attribute so the
    -- MouseLeave handler always restores the CURRENT base, not the creation-time one.
    local function mkBtn(parent, text, width, onClick, accent)
        local b = new("TextButton", {
            Text = text, AutoButtonColor = false,
            FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, Size = UDim2.new(0, width, 0, 26),
            ZIndex = 36, Parent = parent,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        b:SetAttribute("accentBase", accent and true or false)
        local function base()
            return b:GetAttribute("accentBase") and Theme.Palette.Accent or Theme.Palette.TextMuted
        end
        b.TextColor3 = base()
        b.MouseEnter:Connect(function() tween(b, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Text }) end)
        b.MouseLeave:Connect(function() tween(b, Theme.Animation.Fast, { TextColor3 = base() }) end)
        b.MouseButton1Click:Connect(onClick)
        Koffee.attachBtnHover(b, 0, 0.2)   -- v0.48.0: background eases in with the text
        return b
    end

    -- :: manager card ::
    local card = panel(root, "Config Manager")

    local status = new("TextLabel", {
            Text = "Select a config, or type a name to create one",
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 16), TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd, LayoutOrder = 1, ZIndex = 35, Parent = card,
    })
    local function setStatus(msg, ok)
        status.Text = msg
        status.TextColor3 = ok and Theme.Palette.Success or Theme.Palette.Danger
    end

    -- selected-config state. The dropdown is REBUILT from disk on any data change
    -- (create / delete / refresh) so it always mirrors what's actually saved.
    local selectedName, hasConfigs, currentDD = nil, false, nil
    local rebuildManager   -- fwd decl
    local refreshCloud     -- v0.29.0 fwd decl: cloud card reacts to selection changes

    local ddHolder = new("Frame", {
        Size = UDim2.new(1, 0, 0, 48), BackgroundTransparency = 1,
        LayoutOrder = 2, ZIndex = 35, Parent = card,
    })

    -- action row for the SELECTED config
    local actionRow = new("Frame", {
        Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1,
        LayoutOrder = 3, ZIndex = 35, Parent = card,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6), VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder }) })

    -- new-config row
    local newRow = new("Frame", {
        Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1,
        LayoutOrder = 4, ZIndex = 35, Parent = card,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6), VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder }) })
    local nameBox = new("TextBox", {
            Text = "", PlaceholderText = "New config name...", ClearTextOnFocus = false,
        FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Body,
        TextColor3 = Theme.Palette.Text, PlaceholderColor3 = Theme.Palette.TextFaint,
        BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
        BorderSizePixel = 0, Size = UDim2.new(1, -150, 1, 0),
        TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 1, ZIndex = 36, Parent = newRow,
    }, { corner(5), stroke(Theme.Palette.BorderSubtle),
        new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10) }) })

    -- the `auto` button reflects whether the selected config is the auto-load one
    local autoBtn
    local function refreshAutoLabel()
        if not autoBtn then return end
        local isAuto = selectedName ~= nil and CIO.getAuto() == selectedName
            autoBtn.Text = isAuto and "Auto*" or "Auto"
        autoBtn:SetAttribute("accentBase", isAuto)
        autoBtn.TextColor3 = isAuto and Theme.Palette.Accent or Theme.Palette.TextMuted
    end

    local function needSel()
        if hasConfigs and selectedName then return true end
        setStatus("No config selected", false)
        return false
    end

    -- selected-config actions (read selectedName live)
    mkBtn(actionRow, "Load", 60, function()
        if not needSel() then return end
        local ok, msg = CIO.load(selectedName)
            if ok then setStatus("Loaded: " .. tostring(selectedName), true)
            else setStatus("Load failed: " .. tostring(msg), false) end
    end, true).LayoutOrder = 1
    mkBtn(actionRow, "Overwrite", 90, function()
        if not needSel() then return end
        local ok, msg = CIO.save(selectedName)   -- same filename -> overwrites in place
            if ok then setStatus("Overwrote: " .. tostring(selectedName), true)
            else setStatus("Overwrite failed: " .. tostring(msg), false) end
    end).LayoutOrder = 2
    mkBtn(actionRow, "Rename", 72, function()
        if not needSel() then return end
        if not Shared.openTextPopup then return end
        local from = selectedName
        Shared.openTextPopup("rename config", from, "new name", function(txt)
            local ok, msg = CIO.rename(from, txt)
            if not ok then setStatus("Rename failed: " .. tostring(msg), false); return end
            -- carry the auto-load marker across, or it points at a file that is gone
            if CIO.getAuto() == from then CIO.setAuto(msg) end
            CIO.cloudMetaRename(from, msg)   -- v0.29.0: keep the cloud link on the new name
            selectedName = msg
            rebuildManager()
            setStatus("Renamed: " .. from .. " -> " .. msg, true)
        end)
    end).LayoutOrder = 3
    mkBtn(actionRow, "Delete", 66, function()
        if not needSel() then return end
        local nm = selectedName
        -- v0.0.50 fix (two bugs):
        --   1. CIO.delete's return was discarded: a failed/unavailable delfile
        --      still reported "deleted", and the name stayed on disk.
        --   2. deleting the auto-load config left the _auto_<PlaceId> marker
        --      pointing at a file that no longer exists, so auto-load silently
        --      did nothing every session with no way to notice from the UI.
        local ok = CIO.delete(nm)
        if ok and CIO.getAuto() == nm then CIO.setAuto(nil) end
        if ok then CIO.cloudMetaDrop(nm) end   -- v0.29.0: drop the local cloud link (cloud entry stays)
        selectedName = nil
        rebuildManager()
            if ok then setStatus("Deleted: " .. nm, true)
            else setStatus("Delete failed: " .. nm, false) end
    end).LayoutOrder = 4
    autoBtn = mkBtn(actionRow, "Auto", 58, function()
        if not needSel() then return end
            if CIO.getAuto() == selectedName then CIO.setAuto(nil); setStatus("Auto-load cleared", true)
            else CIO.setAuto(selectedName); setStatus("Auto-load: " .. selectedName, true) end
        refreshAutoLabel()
    end)
    autoBtn.LayoutOrder = 5

    -- new-config actions
    mkBtn(newRow, "Create", 66, function()
        local ok, msg = CIO.save(nameBox.Text)
        if ok then
            selectedName = msg
            nameBox.Text = ""
            rebuildManager()
            setStatus("Created: " .. tostring(msg), true)
            else setStatus("Create failed: " .. tostring(msg), false) end
    end, true).LayoutOrder = 2
    mkBtn(newRow, "Refresh", 66, function() rebuildManager(); setStatus("Refreshed", true) end).LayoutOrder = 3

    -- (re)build the selector from disk, keeping the current selection valid.
    rebuildManager = function()
        local names = CIO.list()
        hasConfigs = (#names > 0)
        if selectedName then
            local found = false
            for _, n in ipairs(names) do if n == selectedName then found = true; break end end
            if not found then selectedName = nil end
        end
        if not selectedName and hasConfigs then selectedName = names[1] end

        if currentDD then currentDD.destroy(); currentDD = nil end
        local options = hasConfigs and names or { "no saved configs" }
            currentDD = dropdown(ddHolder, "Saved Configs", options,
            selectedName or "no saved configs", function(v)
                if hasConfigs then selectedName = v; refreshAutoLabel(); if refreshCloud then refreshCloud() end end
            end)
        refreshAutoLabel()
        if refreshCloud then refreshCloud() end
    end

    -- :: cloud configs card (v0.29.0) ::
    -- Share/sync configs through the cloud. Operates on the SELECTED config above.
    -- Upload creates (you become owner) or overwrites (owner only); download pulls
    -- any 8-char id into a local config; delete/rename hit the cloud (owner only).
    local cloudCard = panel(root, "Cloud Configs")
    local cloudStatus = new("TextLabel", {
            Text = "Select a config above, then upload, or paste an ID to download",
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 16), TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd, LayoutOrder = 1, ZIndex = 35, Parent = cloudCard,
    })
    local function setCloud(msg, ok)
        cloudStatus.Text = msg
        cloudStatus.TextColor3 = ok and Theme.Palette.Success or Theme.Palette.Danger
    end

    -- download row: id box + button
    local dlRow = new("Frame", {
        Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1,
        LayoutOrder = 2, ZIndex = 35, Parent = cloudCard,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6), VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder }) })
    local idBox = new("TextBox", {
            Text = "", PlaceholderText = "Cloud ID (8 chars)...", ClearTextOnFocus = false,
        FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Body,
        TextColor3 = Theme.Palette.Text, PlaceholderColor3 = Theme.Palette.TextFaint,
        BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
        BorderSizePixel = 0, Size = UDim2.new(1, -130, 1, 0),
        TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 1, ZIndex = 36, Parent = dlRow,
    }, { corner(5), stroke(Theme.Palette.BorderSubtle),
        new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10) }) })

    -- cloud action rows (buttons created up front, visibility toggled by refreshCloud)
    local function cloudActionRow(order)
        return new("Frame", {
            Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1,
            LayoutOrder = order, ZIndex = 35, Parent = cloudCard,
        }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
            Padding = UDim.new(0, 6), VerticalAlignment = Enum.VerticalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder }) })
    end
    local cloudRow  = cloudActionRow(3)   -- upload + copy id
    local cloudRow2 = cloudActionRow(4)   -- delete cloud + rename cloud (owner only)

    local busyCloud = false
    local function guard() if busyCloud then return false end busyCloud = true return true end

    local dlBtn = mkBtn(dlRow, "Download", 118, function()
        if not guard() then return end
        local id = idBox.Text
            setCloud("Downloading " .. tostring(id):upper():gsub("%s+", "") .. "...", true)
        task.spawn(function()
            local name, err = CIO.cloudDownload(id)
            if name then
                idBox.Text = ""
                selectedName = name
                rebuildManager()
                setCloud('Downloaded "' .. name .. '"', true)
            else
                setCloud("Download failed: " .. tostring(err), false)
            end
            busyCloud = false
        end)
    end, true)
    dlBtn.LayoutOrder = 2

    local upBtn = mkBtn(cloudRow, "Upload", 100, function()
            if not (hasConfigs and selectedName) then setCloud("No config selected", false); return end
        if not guard() then return end
        local nm = selectedName
        setCloud('uploading "' .. nm .. '"...', true)
        task.spawn(function()
            local id, err = CIO.cloudUpload(nm)
            if id then
                if setclipboard then pcall(setclipboard, id) end
                setCloud("Cloud ID: " .. id .. (setclipboard and " (copied)" or ""), true)
            else
                setCloud("Upload failed: " .. tostring(err), false)
            end
            rebuildManager()
            busyCloud = false
        end)
    end, true)
    upBtn.LayoutOrder = 1

    local copyBtn = mkBtn(cloudRow, "Copy ID", 78, function()
        local meta = selectedName and CIO.cloudMetaFor(selectedName)
            if not (meta and meta.id) then setCloud("Not cloud-linked", false); return end
            if setclipboard and pcall(setclipboard, meta.id) then setCloud("Copied " .. meta.id, true)
            else setCloud("ID: " .. meta.id .. " (no clipboard)", true) end
    end)
    copyBtn.LayoutOrder = 2

    local delBtn = mkBtn(cloudRow2, "Delete Cloud", 108, function()
        if not (hasConfigs and selectedName) then return end
        if not guard() then return end
        local nm = selectedName
            setCloud("Deleting from cloud...", true)
        task.spawn(function()
            local ok, err = CIO.cloudDelete(nm)
            if ok then setCloud("Deleted from cloud (local kept)", true)
            else setCloud("Delete failed: " .. tostring(err), false) end
            rebuildManager()
            busyCloud = false
        end)
    end)
    delBtn.LayoutOrder = 3

    local rnBtn = mkBtn(cloudRow2, "Rename Cloud", 108, function()
        if not (hasConfigs and selectedName) then return end
        if not guard() then return end
        local nm = selectedName
            setCloud("Renaming cloud entry...", true)
        task.spawn(function()
            local ok, err = CIO.cloudRename(nm)   -- pushes the local name up to the cloud
            if ok then setCloud('cloud renamed to "' .. nm .. '"', true)
            else setCloud("Rename failed: " .. tostring(err), false) end
            busyCloud = false
        end)
    end)
    rnBtn.LayoutOrder = 4

    -- upload always shows; copy/delete/rename are contextual (linked / owner-only)
    refreshCloud = function()
        local has   = hasConfigs and selectedName ~= nil
        local meta  = has and CIO.cloudMetaFor(selectedName) or nil
        local owner = has and CIO.cloudIsOwner(selectedName)
        upBtn.Text        = (meta and owner) and "Overwrite" or "Upload"
        copyBtn.Visible   = meta ~= nil
        delBtn.Visible    = has and owner and meta ~= nil
        rnBtn.Visible     = has and owner and meta ~= nil
    end

    rebuildManager()
end)

-- v0.52.0: NPC subsystem. Adds custom models (or whole directories) as targets
-- so aimbot, silent aim and a dedicated ESP treat them like players. Own IIFE
-- for its register budget; publishes Shared.NPC for the Combat engine to read.
;(function()
local NPC = { Entries = {}, Folders = {}, _nid = 0, _fid = 0 }
Shared.NPC = NPC
local UIS = game:GetService("UserInputService")

local function newFolderSettings()
    return {
        DisplayName = "",
        Color = Theme.Palette.Accent,
        Exclude = { ESP = false, Aimbot = false, Silent = false },
        Scale = 1.0,
        YOff = 0,
        Rules = {},
    }
end
local DEFAULTS = newFolderSettings()

-- :: re-acquire ::
-- A model deleted and re-added (even renamed) is matched by class shape under
-- its old parent, so its folder + settings survive within a session.
local function signature(inst)
    if not inst then return "" end
    local counts = {}
    for _, ch in ipairs(inst:GetChildren()) do
        counts[ch.ClassName] = (counts[ch.ClassName] or 0) + 1
    end
    local keys = {}
    for k in pairs(counts) do keys[#keys + 1] = k end
    table.sort(keys)
    local parts = { inst.ClassName }
    for _, k in ipairs(keys) do parts[#parts + 1] = k .. ":" .. counts[k] end
    return table.concat(parts, ",")
end
local function findBySig(parent, sig)
    if not parent then return nil end
    for _, ch in ipairs(parent:GetChildren()) do
        if ch:IsA("Model") and signature(ch) == sig then return ch end
    end
    return nil
end

local function folderById(id)
    for _, f in ipairs(NPC.Folders) do if f.id == id then return f end end
    return nil
end
local function settingsFor(entry)
    local f = entry.folderId and folderById(entry.folderId)
    return (f and f.settings) or DEFAULTS
end

local function resolveEntry(entry)
    local inst = entry._inst
    if not (inst and inst.Parent) then
        inst = Shared.resolvePath(entry.path)
        if not (inst and inst.Parent) then
            local parent = entry._parentPath and Shared.resolvePath(entry._parentPath)
            inst = (parent and findBySig(parent, entry.sig)) or nil
        end
        entry._inst = inst
        if inst then entry.path = Shared.pathOf(inst); entry.name = inst.Name end
    end
    if not inst then return {} end
    if entry.kind == "dir" then
        local out = {}
        for _, ch in ipairs(inst:GetChildren()) do
            if ch:IsA("Model") and ch:FindFirstChildOfClass("Humanoid") then out[#out + 1] = ch end
        end
        return out
    end
    return { inst }
end

-- read a value off a model for a Name or Health rule (child value, attribute,
-- or a direct property). Missing reads return nil so the default is kept.
local function readByRule(model, rule)
    if not (model and rule and rule.key and rule.key ~= "") then return nil end
    local src = rule.src or "child"
    if src == "attribute" then
        return model:GetAttribute(rule.key)
    elseif src == "property" then
        local ok, v = pcall(function() return model[rule.key] end)
        return ok and v or nil
    end
    local ch = model:FindFirstChild(rule.key, true)
    if not ch then return nil end
    local ok, v = pcall(function() return ch.Value end)
    if ok and v ~= nil then return v end
    return ch.Name
end

local function wrapperFor(entry, model)
    entry._wrappers = entry._wrappers or {}
    local w = entry._wrappers[model]
    if not w then
        w = { Character = model, Name = model.Name, DisplayName = model.Name, _npc = true }
        entry._wrappers[model] = w
    end
    return w
end

-- flat list of live NPC entities, TTL-memoised so aim + silent + trigger + ESP
-- share one resolve per frame. Each row quacks like a player for the engine.
function NPC.entities()
    local now = os.clock()
    if NPC._cache and (now - (NPC._cacheAt or 0)) < 0.03 then return NPC._cache end
    local out = {}
    for _, entry in ipairs(NPC.Entries) do
        local m = Modules[entry.moduleId]
        if m and m.Enabled then
            local st = settingsFor(entry)
            for _, model in ipairs(resolveEntry(entry)) do
                local hum = model:FindFirstChildOfClass("Humanoid")
                if hum then
                    local nm = st.DisplayName ~= "" and st.DisplayName or model.Name
                    local hp = hum.Health
                    for _, rule in ipairs(st.Rules) do
                        if rule.kind == "Name" then
                            local v = readByRule(model, rule)
                            if v ~= nil then nm = tostring(v) end
                        elseif rule.kind == "Health" then
                            local v = tonumber(readByRule(model, rule))
                            if v then hp = v end
                        end
                    end
                    local w = wrapperFor(entry, model)
                    w.Name, w.DisplayName = nm, nm
                    out[#out + 1] = {
                        wrapper = w, char = model, hum = hum, name = nm, health = hp,
                        exclude = st.Exclude, color = st.Color, scale = st.Scale, yoff = st.YOff,
                    }
                end
            end
        end
    end
    NPC._cache, NPC._cacheAt = out, now
    return out
end
function NPC.targetEntities(feature)
    local out = {}
    for _, e in ipairs(NPC.entities()) do
        if not (e.exclude and e.exclude[feature]) then out[#out + 1] = e end
    end
    return out
end

-- :: dedicated NPC ESP (player ESP is deeply player-keyed, left untouched) ::
local espLayer = KID.track(new("Folder", { Name = KID.name("npc_esp"), Parent = screen }))
local espPool = {}
local function espItem(model)
    local it = espPool[model]
    if it then return it end
    local box = new("Frame", {
        BackgroundTransparency = 1, BorderSizePixel = 0, Visible = false, ZIndex = 10, Parent = espLayer,
    }, { stroke(Theme.Palette.Accent, 1) })
    local nameL = new("TextLabel", {
        Text = "", FontFace = Theme.Fonts.Bold, TextSize = 13, TextColor3 = Theme.Palette.Text,
        BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 14), Position = UDim2.new(0, 0, 0, -16),
        ZIndex = 11, Parent = box,
    }, { textStroke(Color3.new(0, 0, 0), 1) })
    local infoL = new("TextLabel", {
        Text = "", FontFace = Theme.Fonts.Mono, TextSize = 11, TextColor3 = Theme.Palette.TextMuted,
        BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 12), Position = UDim2.new(0, 0, 1, 2),
        ZIndex = 11, Parent = box,
    }, { textStroke(Color3.new(0, 0, 0), 1) })
    it = { box = box, nameL = nameL, infoL = infoL }
    espPool[model] = it
    return it
end
RunService.RenderStepped:Connect(function()
    if Koffee.dead() then return end
    local cam = Workspace.CurrentCamera
    local seen = {}
    if cam and NPC.Enabled ~= false then
        local camPos = cam.CFrame.Position
        for _, e in ipairs(NPC.entities()) do
            if not (e.exclude and e.exclude.ESP) then
                local model = e.char
                local okbb, cf, size = pcall(function() return model:GetBoundingBox() end)
                if okbb and cf and size then
                    local sc = e.scale or 1
                    local hx, hy, hz = size.X * 0.5 * sc, size.Y * 0.5 * sc, size.Z * 0.5 * sc
                    local center = cf.Position + Vector3.new(0, e.yoff or 0, 0)
                    local base = cf - cf.Position + center
                    local minx, miny, maxx, maxy, front = math.huge, math.huge, -math.huge, -math.huge, 0
                    for xi = -1, 1, 2 do for yi = -1, 1, 2 do for zi = -1, 1, 2 do
                        local sp = cam:WorldToViewportPoint(base * Vector3.new(hx * xi, hy * yi, hz * zi))
                        if sp.Z > 0 then
                            front = front + 1
                            if sp.X < minx then minx = sp.X end
                            if sp.Y < miny then miny = sp.Y end
                            if sp.X > maxx then maxx = sp.X end
                            if sp.Y > maxy then maxy = sp.Y end
                        end
                    end end end
                    if front >= 4 and maxx > minx and maxy > miny then
                        seen[model] = true
                        local it = espItem(model)
                        it.box.Position = UDim2.fromOffset(minx, miny)
                        it.box.Size = UDim2.fromOffset(maxx - minx, maxy - miny)
                        it.box.Visible = true
                        local uis = it.box:FindFirstChildOfClass("UIStroke")
                        if uis then uis.Color = e.color or Theme.Palette.Accent end
                        it.nameL.Text = e.name
                        it.nameL.TextColor3 = e.color or Theme.Palette.Text
                        it.infoL.Text = string.format("%d hp  %dm",
                            math.floor(e.health or 0), math.floor((center - camPos).Magnitude + 0.5))
                    end
                end
            end
        end
    end
    for model, it in pairs(espPool) do
        if not seen[model] then
            if not (model and model.Parent) then it.box:Destroy(); espPool[model] = nil
            else it.box.Visible = false end
        end
    end
end)

-- :: model preview + profile viewport ::
local function makeViewport(parent, model, opts)
    opts = opts or {}
    local vp = new("ViewportFrame", {
        BackgroundColor3 = Theme.Palette.Background, BackgroundTransparency = 0.2,
        Size = opts.size or UDim2.fromOffset(40, 40), LayoutOrder = opts.order or 0,
        ZIndex = opts.z or 11, Parent = parent,
    }, { corner(opts.round or 6), stroke(Theme.Palette.BorderSubtle) })
    local cam = new("Camera", { Parent = vp })
    vp.CurrentCamera = cam
    local okc, clone = pcall(function() return model:Clone() end)
    if not okc or not clone then return vp end
    clone.Parent = vp
    local cf, size = model:GetBoundingBox()
    local center, radius = cf.Position, math.max(size.X, size.Y, size.Z)
    if opts.top then
        center = cf.Position + Vector3.new(0, size.Y * 0.30, 0)
        radius = math.max(size.X, size.Y * 0.55)
    end
    local dist = radius * (opts.zoom or 1.6) + 2
    local function look(angle)
        local off = Vector3.new(math.sin(angle), 0.15, math.cos(angle)) * dist
        cam.CFrame = CFrame.lookAt(center + off, center)
    end
    look(opts.angle or 0)
    if opts.spin then
        local a, conn = 0, nil
        conn = RunService.RenderStepped:Connect(function(dt)
            if Koffee.dead() or not vp.Parent then conn:Disconnect(); return end
            a = a + dt * 1.2
            look(a)
        end)
    end
    return vp
end
local function openPreview(model)
    local holder = new("Frame", {
        Size = UDim2.fromOffset(240, 264), BackgroundColor3 = Theme.Palette.Panel,
        BorderSizePixel = 0, ZIndex = 250, Parent = popupScreen,
    }, { corner(10), stroke(Theme.Palette.BorderSubtle) })
    local mp = UIS:GetMouseLocation()
    local vpx = math.clamp(mp.X, 8, math.max(8, workspace.CurrentCamera.ViewportSize.X - 248))
    local vpy = math.clamp(mp.Y, 8, math.max(8, workspace.CurrentCamera.ViewportSize.Y - 272))
    holder.Position = UDim2.fromOffset(vpx, vpy)
    new("TextLabel", {
        Text = model.Name, FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.new(0, 12, 0, 8), Size = UDim2.new(1, -44, 0, 16), ZIndex = 251, Parent = holder,
    })
    local closeBtn = new("TextButton", {
        Text = "", BackgroundColor3 = Theme.Palette.Pill, Size = UDim2.fromOffset(22, 22),
        Position = UDim2.new(1, -28, 0, 6), ZIndex = 251, Parent = holder,
    }, { corner(6) })
    Koffee.lucideIcon(closeBtn, "x", 13, Theme.Palette.TextMuted)
    closeBtn.MouseButton1Click:Connect(function() holder:Destroy() end)
    makeViewport(holder, model, {
        size = UDim2.new(1, -20, 1, -44), z = 251, spin = true,
    }).Position = UDim2.fromOffset(10, 34)
end

-- :: entry / folder mutation ::
local function addEntry(inst, kind)
    NPC._nid = NPC._nid + 1
    local id = NPC._nid
    local entry = {
        id = id, kind = kind, path = Shared.pathOf(inst),
        _parentPath = inst.Parent and Shared.pathOf(inst.Parent) or nil,
        sig = signature(inst), name = inst.Name, folderId = nil, _inst = inst,
        moduleId = "npc_" .. id,
    }
    registerModule(entry.moduleId, "npc: " .. inst.Name, function() end, function() end)
    NPC.Entries[#NPC.Entries + 1] = entry
    toggleModule(entry.moduleId)   -- active by default (also lists it in the arraylist)
    return entry
end
local function removeEntry(entry)
    local m = Modules[entry.moduleId]
    if m and m.Enabled then toggleModule(entry.moduleId) end
    for i, e in ipairs(NPC.Entries) do if e == entry then table.remove(NPC.Entries, i) break end end
end
local function addFolder(name)
    NPC._fid = NPC._fid + 1
    local f = { id = NPC._fid, name = name or ("Folder " .. NPC._fid), settings = newFolderSettings() }
    NPC.Folders[#NPC.Folders + 1] = f
    return f
end
local function removeFolder(f)
    for _, e in ipairs(NPC.Entries) do if e.folderId == f.id then e.folderId = nil end end
    for i, x in ipairs(NPC.Folders) do if x == f then table.remove(NPC.Folders, i) break end end
end

-- :: small UI helpers (mkBtn / labelRow are tab-local elsewhere) ::
local function clearKids(f)
    for _, c in ipairs(f:GetChildren()) do
        if not c:IsA("UIListLayout") and not c:IsA("UIPadding") then c:Destroy() end
    end
end
local function hintRow(parent, s, order)
    return new("TextLabel", {
        Text = s, FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1, TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left, AutomaticSize = Enum.AutomaticSize.Y,
        Size = UDim2.new(1, 0, 0, 14), LayoutOrder = order or 0, Parent = parent,
    })
end
local function iconBtn(parent, icon, tip, cb, order)
    local b = new("TextButton", {
        Text = "", BackgroundColor3 = Theme.Palette.Pill, AutoButtonColor = true,
        Size = UDim2.fromOffset(22, 22), LayoutOrder = order or 0, Parent = parent,
    }, { corner(6), stroke(Theme.Palette.BorderSubtle) })
    Koffee.lucideIcon(b, icon, 13, Theme.Palette.TextMuted)
    b.MouseButton1Click:Connect(cb)
    if tip and tip ~= "" then b.Name = tip end
    return b
end
local function textBtn(parent, label, cb, order)
    local b = new("TextButton", {
        Text = label, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.Text, BackgroundColor3 = Theme.Palette.Pill, AutoButtonColor = true,
        AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 0, 26), LayoutOrder = order or 0, Parent = parent,
    }, { corner(6), stroke(Theme.Palette.BorderSubtle),
        new("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }) })
    b.MouseButton1Click:Connect(cb)
    return b
end
local function textInput(parent, placeholder, initial, order, onCommit)
    local tb = new("TextBox", {
        Text = initial or "", PlaceholderText = placeholder, ClearTextOnFocus = false,
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.Text,
        PlaceholderColor3 = Theme.Palette.TextFaint, BackgroundColor3 = Theme.Palette.Background,
        BackgroundTransparency = 0.15, Size = UDim2.new(1, 0, 0, 26), TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = order or 0, Parent = parent,
    }, { corner(6), stroke(Theme.Palette.BorderSubtle),
        new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }) })
    tb.FocusLost:Connect(function() onCommit(tb.Text) end)
    return tb
end
local function vlist(parent, pad, order, width)
    return new("Frame", {
        Size = width or UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1, LayoutOrder = order or 0, Parent = parent,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical,
        Padding = UDim.new(0, pad or 6), SortOrder = Enum.SortOrder.LayoutOrder }) })
end
local function hrow(parent, height, order)
    return new("Frame", {
        Size = UDim2.new(1, 0, 0, height or 26), BackgroundTransparency = 1, LayoutOrder = order or 0, Parent = parent,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6),
        VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
end

-- :: PICKER sub-tab ::
local function buildPicker(host, onChange)
    hintRow(host, "Scan finds models with a Humanoid. Add one, or Browse to pick any model or directory. Right-click a result for a 360 preview.", 0)
    local controls = hrow(host, 28, 1)
    local listWrap = new("ScrollingFrame", {
        Size = UDim2.new(1, 0, 0, 240), BackgroundColor3 = Theme.Palette.Background, BackgroundTransparency = 0.35,
        BorderSizePixel = 0, ScrollBarThickness = 4, ScrollBarImageColor3 = Theme.Palette.TextFaint,
        CanvasSize = UDim2.new(0, 0, 0, 0), AutomaticCanvasSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = host,
    }, { corner(6), new("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 6),
        PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }),
        new("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }) })

    local function scanCandidates()
        local out, seen = {}, {}
        local function consider(m)
            if m:IsA("Model") and m ~= LocalPlayer.Character and not seen[m]
                and m:FindFirstChildOfClass("Humanoid") then
                local isPlayer = false
                for _, pl in ipairs(Players:GetPlayers()) do
                    if pl.Character == m then isPlayer = true break end
                end
                if not isPlayer then seen[m] = true; out[#out + 1] = m end
            end
        end
        for _, c in ipairs(Workspace:GetChildren()) do
            consider(c)
            if c:IsA("Folder") or c:IsA("Model") then
                for _, gc in ipairs(c:GetChildren()) do consider(gc) end
            end
        end
        return out
    end

    local function candRow(model)
        local row = new("Frame", {
            Size = UDim2.new(1, 0, 0, 40), BackgroundColor3 = Theme.Palette.PanelElevated,
            BackgroundTransparency = 0.4, BorderSizePixel = 0, Parent = listWrap,
        }, { corner(6) })
        makeViewport(row, model, { size = UDim2.fromOffset(32, 32), round = 6, top = true }).Position = UDim2.new(0, 4, 0.5, -16)
        new("TextLabel", {
            Text = model.Name, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextTruncate = Enum.TextTruncate.AtEnd,
            TextXAlignment = Enum.TextXAlignment.Left, Position = UDim2.new(0, 44, 0, 0),
            Size = UDim2.new(1, -140, 1, 0), Parent = row,
        })
        local addB = new("TextButton", {
            Text = "Add", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Background, BackgroundColor3 = Theme.Palette.Accent, AutoButtonColor = true,
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -8, 0.5, 0), Size = UDim2.fromOffset(56, 26), Parent = row,
        }, { corner(6) })
        addB.MouseButton1Click:Connect(function()
            addEntry(model, "model")
            addB.Text = "Added"
            if onChange then onChange() end
        end)
        row.InputBegan:Connect(function(io)
            if io.UserInputType == Enum.UserInputType.MouseButton2 then openPreview(model) end
        end)
    end

    local function rescan()
        for _, c in ipairs(listWrap:GetChildren()) do
            if not c:IsA("UIListLayout") and not c:IsA("UIPadding") then c:Destroy() end
        end
        local found = scanCandidates()
        if #found == 0 then hintRow(listWrap, "No Humanoid models found in Workspace. Use Browse.", 0) return end
        for _, m in ipairs(found) do candRow(m) end
    end

    textBtn(controls, "Scan", rescan, 1)
    textBtn(controls, "Browse", function()
        if not Shared.openInstancePicker then return end
        Shared.openInstancePicker(function(inst)
            if not inst then return end
            local kind = (inst:IsA("Model") and inst:FindFirstChildOfClass("Humanoid")) and "model" or "dir"
            addEntry(inst, kind)
            if onChange then onChange() end
        end, { anyInstance = true, title = "Pick an NPC model or a directory",
            subtitle = "A Humanoid model becomes one NPC; any other container becomes a directory of NPCs." })
    end, 2)
    rescan()
end

-- :: MANAGER sub-tab ::
local function buildManager(host)
    local selected = nil   -- selected folder (settings target)
    local expanded = {}
    local cols = new("Frame", {
        Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Parent = host,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 10),
        SortOrder = Enum.SortOrder.LayoutOrder }) })
    local left = vlist(cols, 6, 1, UDim2.new(0.52, -5, 0, 0))
    local right = vlist(cols, 6, 2, UDim2.new(0.48, -5, 0, 0))
    local listBox = nil
    local rebuild, showSettings

    local function entryRow(parent, entry, indent)
        local row = new("Frame", {
            Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = Theme.Palette.PanelElevated,
            BackgroundTransparency = 0.5, BorderSizePixel = 0, Parent = parent,
        }, { corner(6), new("UIPadding", { PaddingLeft = UDim.new(0, indent or 8), PaddingRight = UDim.new(0, 6) }),
            new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6),
                VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
        Koffee.lucideIcon(row, entry.kind == "dir" and "folder-open" or "user", 14, Theme.Palette.TextMuted).LayoutOrder = 0
        new("TextLabel", {
            Text = entry.name, FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextTruncate = Enum.TextTruncate.AtEnd,
            TextXAlignment = Enum.TextXAlignment.Left, Size = UDim2.new(1, -70, 1, 0), LayoutOrder = 1, Parent = row,
        })
        -- assign to / remove from a folder. Its own wrapper so rightClickSettings
        -- (which grabs the first TextButton it finds) targets exactly this button.
        local assignWrap = new("Frame", {
            Size = UDim2.fromOffset(22, 22), BackgroundTransparency = 1, LayoutOrder = 2, Parent = row,
        })
        local assignBtn = new("TextButton", {
            Text = "", BackgroundColor3 = Theme.Palette.Pill, AutoButtonColor = true, Size = UDim2.fromScale(1, 1), Parent = assignWrap,
        }, { corner(6), stroke(Theme.Palette.BorderSubtle) })
        Koffee.lucideIcon(assignBtn, "folder", 13, Theme.Palette.TextMuted)
        rightClickSettings(assignWrap, "Assign folder", function(api)
            local names = { "None" }
            for _, f in ipairs(NPC.Folders) do names[#names + 1] = f.name end
            local cur = "None"
            if entry.folderId then local f = folderById(entry.folderId); if f then cur = f.name end end
            api:dropdown("Folder", names, cur, function(v)
                if v == "None" then entry.folderId = nil
                else
                    for _, f in ipairs(NPC.Folders) do if f.name == v then entry.folderId = f.id break end end
                end
                rebuild()
            end)
        end, true)
        iconBtn(row, "trash-2", "remove", function() removeEntry(entry); rebuild() end, 3)
    end

    local function folderHeader(parent, folder)
        local row = new("Frame", {
            Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = Theme.Palette.Pill,
            BackgroundTransparency = (selected == folder) and 0.1 or 0.5, BorderSizePixel = 0, Parent = parent,
        }, { corner(6), new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }),
            new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6),
                VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
        local chev = iconBtn(row, expanded[folder.id] and "chevron-down" or "chevron-right", "", function()
            expanded[folder.id] = not expanded[folder.id]; rebuild()
        end, 0)
        chev.BackgroundTransparency = 1
        -- name is a button so the whole label selects the folder (no overlay button,
        -- which a horizontal UIListLayout would lay out inline instead of stacking).
        local nameBtn = new("TextButton", {
            Text = folder.name, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextTruncate = Enum.TextTruncate.AtEnd,
            AutoButtonColor = false, TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, -96, 1, 0), LayoutOrder = 1, Parent = row,
        })
        nameBtn.MouseButton1Click:Connect(function() selected = folder; showSettings(); rebuild() end)
        iconBtn(row, "pencil", "rename", function()
            nameBtn.Visible = false
            local tb = textInput(row, "folder name", folder.name, 1, function(t)
                if t ~= "" then folder.name = t end
                rebuild()
            end)
            tb.Size = UDim2.new(1, -96, 0, 22)
            tb:CaptureFocus()
        end, 2)
        iconBtn(row, "trash-2", "delete folder", function()
            if selected == folder then selected = nil; showSettings() end
            removeFolder(folder); rebuild()
        end, 3)
    end

    rebuild = function()
        clearKids(left)
        textBtn(left, "New Folder", function() local f = addFolder(); expanded[f.id] = true; rebuild() end, 0)
        listBox = vlist(left, 4, 1)
        for _, folder in ipairs(NPC.Folders) do
            folderHeader(listBox, folder)
            if expanded[folder.id] then
                local any = false
                for _, e in ipairs(NPC.Entries) do
                    if e.folderId == folder.id then entryRow(listBox, e, 20); any = true end
                end
                if not any then hintRow(listBox, "  (empty, assign NPCs from Ungrouped)", 0) end
            end
        end
        -- ungrouped
        local ung = {}
        for _, e in ipairs(NPC.Entries) do if not e.folderId then ung[#ung + 1] = e end end
        if #ung > 0 then
            new("TextLabel", {
                Text = "Ungrouped", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
                Size = UDim2.new(1, 0, 0, 16), Parent = listBox,
            })
            for _, e in ipairs(ung) do entryRow(listBox, e, 8) end
        end
        if #NPC.Entries == 0 then hintRow(listBox, "No NPCs yet. Add some in the Picker tab.", 0) end
    end

    showSettings = function()
        clearKids(right)
        if not selected then
            hintRow(right, "Select a folder to edit its name, exclusions, offsets and rules.", 0)
            return
        end
        local f, st = selected, selected.settings
        new("TextLabel", {
            Text = "Folder: " .. f.name, FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Body,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, 0, 0, 16), LayoutOrder = 0, Parent = right,
        })
        -- right panel uses pure creation order (all LayoutOrder 0), like the rest
        -- of the file: sliders never set LayoutOrder, so mixing explicit orders in
        -- would jump them to the top.
        hintRow(right, "Display name (blank uses the model name):", 0)
        textInput(right, "override name", st.DisplayName, 0, function(t) st.DisplayName = t end)
        local cRow = hrow(right, 20, 0)
        new("TextLabel", {
            Text = "ESP Color", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, -30, 1, 0), LayoutOrder = 0, Parent = cRow,
        })
        colorSwatch(cRow, st.Color, 16, { onChange = function(c) st.Color = c end })
        configCheckbox(right, "Exclude from ESP", st.Exclude.ESP, function(v) st.Exclude.ESP = v end)
        configCheckbox(right, "Exclude from Aimbot", st.Exclude.Aimbot, function(v) st.Exclude.Aimbot = v end)
        configCheckbox(right, "Exclude from Silent", st.Exclude.Silent, function(v) st.Exclude.Silent = v end)
        slider(right, "ESP Scale", 0.2, 3, st.Scale, 2, function(v) st.Scale = v end)
        slider(right, "Vertical Offset", -10, 10, st.YOff, 1, function(v) st.YOff = v end)
        hintRow(right, "Rules read a value off each model (child .Value, attribute, or property):", 0)
        local ruleBox = vlist(right, 4, 0)
        local addRow = hrow(right, 26, 0)
        local function drawRules()
            clearKids(ruleBox)
            for _, rule in ipairs(st.Rules) do
                local rr = hrow(ruleBox, 26, 0)
                new("TextLabel", {
                    Text = rule.kind, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                    TextColor3 = Theme.Palette.Accent, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
                    Size = UDim2.fromOffset(52, 22), LayoutOrder = 0, Parent = rr,
                })
                local dd = dropdown(rr, "", { "child", "attribute", "property" }, rule.src or "child",
                    function(v) rule.src = v end)
                dd.frame.Size = UDim2.fromOffset(90, 26)
                dd.frame.LayoutOrder = 1
                local ti = textInput(rr, "key / name", rule.key, 2, function(t) rule.key = t end)
                ti.Size = UDim2.new(1, -180, 0, 26)
                iconBtn(rr, "trash-2", "remove rule", function()
                    for i, x in ipairs(st.Rules) do if x == rule then table.remove(st.Rules, i) break end end
                    drawRules()
                end, 3)
            end
        end
        textBtn(addRow, "+ Name Rule", function()
            st.Rules[#st.Rules + 1] = { kind = "Name", src = "child", key = "" }; drawRules()
        end, 0)
        textBtn(addRow, "+ Health Rule", function()
            st.Rules[#st.Rules + 1] = { kind = "Health", src = "child", key = "" }; drawRules()
        end, 1)
        drawRules()
    end

    rebuild()
    showSettings()
    return rebuild
end

function NPC.buildTab(root)
    local card = panel(root)
    local S = Shared.subTabs(card, { "Picker", "Manager" })
    local managerRebuild
    buildPicker(S.Picker, function() if managerRebuild then managerRebuild() end end)
    managerRebuild = buildManager(S.Manager)
end
end)()

-- v0.45.2: Teams is now Extra. NPC now has a real builder (v0.52.0); the IIFE
-- above owns the subsystem and publishes Shared.NPC.buildTab.
addTab("NPC", function(root) Shared.NPC.buildTab(root) end)
-- v0.46.0: Extra grows its first sub-tab, Mods: the universal stat mod
-- from gun research. Pick a source (held tool / any instance), tick values,
-- pin them held or set-once. Session-only, unpin to restore.
addTab("Extra", function(epanel)
    -- v0.48.3: no card title: Combat/Custom cards are titleless so the
    -- secondary bar sits at the very top of the feature box. Same here.
    local card = panel(epanel)
    local R = Shared.subTabs and Shared.subTabs(card, { "Mods" }) or nil
    local host = (R and R["Mods"]) or card
    -- pins live across rescans, keyed so a rebuild re-attaches, not dupes.
    -- { on, want, orig, kind } / kind = number|bool|string.
    local pins = {}
    local rows = {}   -- id -> { cur, entry } for the heartbeat refresh
    local srcLabel, listBox
    local current = { mode = "none", inst = nil, path = "" }

    local function entryId(srcId, sub, name) return srcId .. "|" .. sub .. "|" .. name end
    local function srcId()
        if current.mode == "tool" then return "tool:" .. (current.toolName or "?") end
        return "path:" .. current.path
    end
    local function resolveRoot()
        if current.mode == "tool" then
            local ch = LocalPlayer and LocalPlayer.Character
            -- follow the gun into the backpack: Tools leave the character
            -- on unequip, and pins silently dying with them is a trap.
            local nm = current.toolName
            local t = ch and nm and ch:FindFirstChild(nm)
            if t and t:IsA("Tool") then return t end
            local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
            t = bp and nm and bp:FindFirstChild(nm)
            if t and t:IsA("Tool") then return t end
            return nil
        elseif current.mode == "picked" then
            if current.inst and current.inst.Parent then return current.inst end
            if current.path ~= "" and Shared.resolvePath then
                local ok, inst = pcall(Shared.resolvePath, current.path)
                if ok and inst and inst.Parent then
                    current.inst = inst
                    return inst
                end
            end
        end
        return nil
    end
    local function resolveEntry(e)
        local root = resolveRoot()
        if not root then return nil end
        local node = root
        if e.sub ~= "" then
            node = root:FindFirstChild(e.sub)
            if not node then return nil end
        end
        if e.isAttr then
            local v = node:GetAttribute(e.name)
            return (v ~= nil) and { attr = true, node = node } or nil
        end
        local v = node:FindFirstChild(e.name)
        if v and (v:IsA("IntValue") or v:IsA("NumberValue")
            or v:IsA("BoolValue") or v:IsA("StringValue")) then return v end
        return nil
    end
    local function readEntry(e)
        local h = resolveEntry(e)
        if not h then return nil end
        if e.isAttr then return h.node:GetAttribute(e.name) end
        return h.Value
    end
    local function writeEntry(e, want)
        local h = resolveEntry(e)
        if not h then return false end
        if e.isAttr then
            local ok = pcall(function() h.node:SetAttribute(e.name, want) end)
            return ok
        end
        local ok = pcall(function() h.Value = want end)
        return ok
    end
    local function fmt(v)
        local t = typeof(v)
        if t == "number" then
            return tostring(math.floor(v * 1000 + 0.5) / 1000)
        elseif t == "boolean" then
            return v and "true" or "false"
        elseif t == "string" then
            return #v > 18 and (v:sub(1, 17) .. "..") or v
        end
        return "?"
    end
    -- v0.46.2: instant re-assert. Polling loses to games that rewrite the
    -- value every frame (spread bloom): the changed signal wins it back
    -- the same frame. Heartbeat re-hooks after round rebuilds.
    local function unhookPin(pin)
        if pin.conn then pcall(function() pin.conn:Disconnect() end) end
        pin.conn, pin.hookInst = nil, nil
    end
    local function hookPin(pin, e)
        unhookPin(pin)
        local h = resolveEntry(e)
        if not h then return end
        local inst = e.isAttr and h.node or h
        local sig = e.isAttr and h.node:GetAttributeChangedSignal(e.name)
            or h:GetPropertyChangedSignal("Value")
        if not sig then return end
        pin.hookInst = inst
        pin.conn = sig:Connect(function()
            if not pin.on then return end
            local cur = readEntry(e)
            if cur ~= nil and pin.want ~= nil and cur ~= pin.want then
                writeEntry(e, pin.want)
            end
        end)
        if pin.want ~= nil then writeEntry(e, pin.want) end
    end
    -- one row: pin toggle | name | live value | editor (box or bool flip).
    -- Enter in the box = set once now. Pin = hold against rewrites.
    local function buildRow(list, e, id, kind)
        local pin = pins[id]
        if not pin then
            pin = { on = false, want = nil, orig = nil, kind = kind }
            pins[id] = pin
        end
        local row = new("Frame", {
            Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1,
            ZIndex = 34, Parent = list,
        }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
            Padding = UDim.new(0, 6), VerticalAlignment = Enum.VerticalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder }) })
        local pinBtn = new("TextButton", {
            Size = UDim2.new(0, 30, 0, 20), BackgroundColor3 = Theme.Palette.PanelElevated,
            BackgroundTransparency = 0.2, BorderSizePixel = 0, AutoButtonColor = false,
            Text = pin.on and "On" or "Off", FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Tiny,
            TextColor3 = pin.on and Theme.Palette.Accent or Theme.Palette.TextMuted,
            LayoutOrder = 1, ZIndex = 35, Parent = row,
        }, { pillCorner() })
        popFx(pinBtn)   -- v0.48.0: pin flips squash on press
        Koffee.attachBtnHover(pinBtn, 0, 0.2)   -- v0.48.0: background eases in on hover
        new("TextLabel", {
            Text = (e.sub ~= "" and (e.sub .. ".") or "") .. e.name .. (e.isAttr and " *" or ""),
            FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1,
            Size = UDim2.new(1, -190, 1, 0), TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            LayoutOrder = 2, ZIndex = 35, Parent = row,
        })
        local cur = new("TextLabel", {
            Text = "", FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Tiny,
            TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
            Size = UDim2.new(0, 64, 1, 0), TextXAlignment = Enum.TextXAlignment.Right,
            TextTruncate = Enum.TextTruncate.AtEnd,
            LayoutOrder = 3, ZIndex = 35, Parent = row,
        })
        rows[id] = { cur = cur, entry = e }
        local function paintPin()
            pinBtn.Text = pin.on and "On" or "Off"
            pinBtn.TextColor3 = pin.on and Theme.Palette.Accent or Theme.Palette.TextMuted
        end
        local function snapOrig()
            if pin.orig == nil then
                local v = readEntry(e)
                if v ~= nil then pin.orig = v end
            end
        end
        pinBtn.MouseButton1Click:Connect(function()
            pin.on = not pin.on
            if pin.on then
                snapOrig()
                hookPin(pin, e)
            else
                unhookPin(pin)
                if pin.orig ~= nil then writeEntry(e, pin.orig) end
            end
            paintPin()
        end)
        if kind == "bool" then
            local flip = new("TextButton", {
                Size = UDim2.new(0, 80, 0, 20), BackgroundColor3 = Theme.Palette.PanelElevated,
                BackgroundTransparency = 0.2, BorderSizePixel = 0, AutoButtonColor = false,
                Text = pin.want ~= nil and tostring(pin.want) or "Set?",
                FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Tiny,
                TextColor3 = Theme.Palette.Text, LayoutOrder = 4, ZIndex = 35, Parent = row,
            }, { pillCorner() })
            popFx(flip)   -- v0.48.0: bool flips squash on press
            Koffee.attachBtnHover(flip, 0, 0.2)   -- v0.48.0: background eases in on hover
            flip.MouseButton1Click:Connect(function()
                local v = readEntry(e)
                pin.want = not (v == true)
                if pin.want == false and v == false then pin.want = true end
                snapOrig()
                writeEntry(e, pin.want)
                flip.Text = tostring(pin.want)
            end)
        else
            local box = new("TextBox", {
                Size = UDim2.new(0, 80, 0, 20),
                Text = pin.want ~= nil and tostring(pin.want) or "",
                PlaceholderText = kind == "number" and "Num" or "Text",
                ClearTextOnFocus = false, FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Tiny,
                TextColor3 = Theme.Palette.Text, PlaceholderColor3 = Theme.Palette.TextFaint,
                BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
                BorderSizePixel = 0, LayoutOrder = 4, ZIndex = 35, Parent = row,
            }, { pillCorner() })
            box.FocusLost:Connect(function(enter)
                if not enter then return end
                local w = kind == "number" and tonumber(box.Text) or box.Text
                if w == nil or (kind ~= "number" and w == "") then return end
                pin.want = w
                snapOrig()
                writeEntry(e, w)
            end)
        end
        return row   -- v0.48.0: scan() staggers rows in on rebuild
    end
    -- v0.46.1: common gun-value patterns. Substring match on the lowercase
    -- name: games rename everything, but ammo/damage/rate always read alike.
    local COMMON_GUN = { "ammo", "clip", "mag", "reserve", "storedammo",
        "bullet", "damage", "dmg", "headshot", "firerate", "rateoffire",
        "rpm", "burst", "cooldown", "reload", "range", "falloff", "spread",
        "recoil", "bloom", "kick", "auto", "suppres", "velocity", "equip",
        "aim", "zoom", "fov", "penetrat", "pellet", "shot" }
    local function isCommonGun(name)
        local q = tostring(name):lower()
        for _, p in ipairs(COMMON_GUN) do
            if q:find(p, 1, true) then return true end
        end
        return false
    end
    local function sectionLbl(list, text)
        new("TextLabel", {
            Text = text, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Tiny,
            TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 12), TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 34, Parent = list,
        })
    end
    local function scan()
        for _, c in ipairs(listBox:GetChildren()) do
            if c:IsA("Frame") or c:IsA("TextLabel") then c:Destroy() end
        end
        rows = {}
        local root = resolveRoot()
        if not root then
            srcLabel.Text = current.mode == "none" and "Hold a gun, or pick an instance"
                or "Source gone: rescan"
            return
        end
        srcLabel.Text = (current.mode == "tool" and "tool: " or "instance: ") .. root.Name
        local sid = srcId()
        local seen = {}
        local common, rest = {}, {}
        local function add(sub, v, isAttr, aname)
            local key = sub .. "|" .. (isAttr and ("@" .. aname) or v.Name)
            if seen[key] then return end
            seen[key] = true
            local kind = "string"
            if not isAttr then
                kind = v:IsA("BoolValue") and "bool"
                    or ((v:IsA("IntValue") or v:IsA("NumberValue")) and "number" or "string")
            else
                local av = root:GetAttribute(aname)
                local at = typeof(av)
                kind = (at == "number" and "number") or (at == "boolean" and "bool") or "string"
                if at ~= "number" and at ~= "boolean" and at ~= "string" then return end
            end
            local e = { sub = sub, name = isAttr and aname or v.Name, isAttr = isAttr }
            local bucket = isCommonGun(e.name) and common or rest
            bucket[#bucket + 1] = { e = e, kind = kind }
        end
        for _, c in ipairs(root:GetChildren()) do
            if c:IsA("IntValue") or c:IsA("NumberValue")
                or c:IsA("BoolValue") or c:IsA("StringValue") then
                add("", c, false)
            end
        end
        local okA, attrs = pcall(function() return root:GetAttributes() end)
        if okA and attrs then
            for aname in pairs(attrs) do add("", nil, true, aname) end
        end
        -- one level into Folders (Gunfight-style Variables pattern).
        for _, c in ipairs(root:GetChildren()) do
            if c:IsA("Folder") then
                for _, k in ipairs(c:GetChildren()) do
                    if k:IsA("IntValue") or k:IsA("NumberValue")
                        or k:IsA("BoolValue") or k:IsA("StringValue") then
                        add(c.Name, k, false)
                    end
                end
            end
        end
        local function emit(bucket)
            -- v0.48.0: scanned rows cascade in with a tiny stagger (capped, so
            -- a 60-value gun doesn't take all day). Lists off shows them all.
            local n = 0
            for _, item in ipairs(bucket) do
                local row = buildRow(listBox, item.e, entryId(sid, item.e.sub, item.e.name), item.kind)
                if row and Koffee.Anim.spot("AnimLists") then
                    n = n + 1
                    local sc, target = uScaleOf(row), row
                    sc.Scale = 0.96
                    task.delay(math.min(n * 0.02, 0.4), function()
                        if target.Parent then
                            tween(sc, Theme.Animation.Fast, { Scale = 1 })
                        end
                    end)
                end
            end
        end
        if #common + #rest == 0 then
            srcLabel.Text = root.Name .. ": No tunable values"
            return
        end
        if #common > 0 then sectionLbl(listBox, "common") emit(common) end
        if #rest > 0 then sectionLbl(listBox, "everything else") emit(rest) end
    end
    -- header: source buttons + rescan + restore-all.
    local bar = new("Frame", {
        Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1,
        LayoutOrder = 1, ZIndex = 34, Parent = host,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }) })
    local function hdrBtn(label, order, fn)
        local b = new("TextButton", {
            Size = UDim2.new(0, 86, 0, 22), BackgroundColor3 = Theme.Palette.PanelElevated,
            BackgroundTransparency = 0.2, BorderSizePixel = 0, AutoButtonColor = false,
            Text = label, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, LayoutOrder = order, ZIndex = 35, Parent = bar,
        }, { pillCorner() })
        b.MouseButton1Click:Connect(fn)
        popFx(b)   -- v0.48.0: header buttons squash on press like the rest
        Koffee.attachBtnHover(b, 0, 0.2)   -- v0.48.0: background eases in on hover
        return b
    end
    hdrBtn("Held Tool", 1, function()
        local ch = LocalPlayer and LocalPlayer.Character
        local tool = ch and ch:FindFirstChildOfClass("Tool")
        current = { mode = "tool", toolName = tool and tool.Name or nil,
                    inst = nil, path = "" }
        scan()
    end)
    hdrBtn("Pick...", 2, function()
        if not Shared.openInstancePicker then return end
        Shared.openInstancePicker(function(inst, path)
            if inst then
                current = { mode = "picked", inst = inst, path = path or "" }
                scan()
            end
        end, { title = "pick a gun or template" })
    end)
    hdrBtn("Rescan", 3, function() scan() end)
    hdrBtn("Restore All", 4, function()
        for id, pin in pairs(pins) do
            unhookPin(pin)
            if pin.orig ~= nil and rows[id] then
                writeEntry(rows[id].entry, pin.orig)
            end
            pin.on = false
        end
        scan()
    end)
    srcLabel = new("TextLabel", {
        Text = "Hold a gun, or pick an instance", FontFace = Theme.Fonts.Regular,
        TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
        BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 14),
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 2, ZIndex = 34, Parent = host,
    })
    listBox = new("Frame", {
        Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1, LayoutOrder = 3, ZIndex = 34, Parent = host,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical,
        Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder }) })
    new("TextLabel", {
        Text = "* = attribute. enter in a box = set once. pin = hold. unpin restores.",
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Tiny,
        TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1,
        TextWrapped = true, Size = UDim2.new(1, 0, 0, 22),
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 4, ZIndex = 34, Parent = host,
    })
    -- reassert pins + refresh live values, throttled. Resolves fresh per
    -- tick so round rebuilds re-attach instead of dying on stale refs.
    local lastTick = 0
    RunService.Heartbeat:Connect(function()
        if Koffee.dead() then return end
        local now = os.clock()
        if now - lastTick < 0.5 then return end
        lastTick = now
        for id, pin in pairs(pins) do
            local r = rows[id]
            if r then
                local v = readEntry(r.entry)
                if v == nil then
                    r.cur.Text = "Gone"
                else
                    r.cur.Text = fmt(v)
                    if pin.on then
                        -- re-hook after rebuilds (fresh instance, dead signal).
                        local h = resolveEntry(r.entry)
                        local inst = h and (r.entry.isAttr and h.node or h)
                        if pin.conn == nil or pin.hookInst ~= inst then
                            hookPin(pin, r.entry)
                        elseif pin.want ~= nil and v ~= pin.want then
                            writeEntry(r.entry, pin.want)
                        end
                    end
                end
            end
        end
    end)
end)

-- select first tab AFTER layout AND positioning have settled.
-- v0.0.5 only checked AbsoluteSize: but AbsolutePosition can still be zero
-- for a frame or two after that, which put the pill at (0,0) on first launch.
-- also, the tabBar AbsolutePosition signal above will re-snap once it moves.
task.spawn(function()
    local btn = tabs.Visuals.Button
    for _ = 1, 240 do
        local bp = btn.AbsolutePosition
        local bs = btn.AbsoluteSize
        local tp = tabBar.AbsolutePosition
        if bs.X > 0 and (bp.X ~= 0 or bp.Y ~= 0) and (tp.X ~= 0 or tp.Y ~= 0) then
            break
        end
        RunService.RenderStepped:Wait()
    end
    selectTab("Visuals")
end)

-- v0.0.97: the bottom-right session toast was removed entirely (the user
-- asked to drop the widget, not just the headline label). nothing replaces it.

-- WINDOW TOGGLE + BACKGROUND SYNC
-- Delete key toggles. Everything (window + snow + dim + blur) fades
-- with the same linear timing so they leave together, cleanly.
-- IIFE: own register budget. The main chunk rides Luau's 200-local ceiling
-- (same pattern as the Combat IIFE further up).
;(function()
local windowOpen = true

-- v0.0.95: track pre-open mouse state so we can restore what the game (or 3rd
-- Person, or shift-lock, etc.) was doing after the user closes the menu.
local _preMenuMouseBehavior, _preMenuMouseIcon, _preMenuCamMode = nil, nil, nil
-- v0.18.3: setting MouseBehavior once loses in first person. The PlayerModule's
-- camera re-locks it EVERY frame during camera update, so the fix is to re-assert
-- after it: RenderPriority.Last (2000) runs after Camera (200), where 3rd Person
-- and the aimbot bind.
local MFREE = KID.name("mfree")
local function holdMouseFree(on)
    pcall(function() RunService:UnbindFromRenderStep(MFREE) end)
    if not on then return end
    pcall(function()
        RunService:BindToRenderStep(MFREE, Enum.RenderPriority.Last.Value, function()
            if UserInputService.MouseBehavior ~= Enum.MouseBehavior.Default then
                UserInputService.MouseBehavior = Enum.MouseBehavior.Default
            end
            if not UserInputService.MouseIconEnabled then
                UserInputService.MouseIconEnabled = true
            end
        end)
    end)
end
local function setWindowOpen(open)
    if windowOpen == open then return end
    windowOpen = open
    if open then
        window.Visible = true
        -- v0.48.0: window open honours the Animations > Window Open flag; off
        -- snaps straight to the resting state instead of fading + growing in.
        if Koffee.Anim.spot("AnimWindow") then
            window.GroupTransparency = 1
            local wsc = uScaleOf(window)   -- v0.0.98: window pops open (fade + grow)
            wsc.Scale = 0.90
            tween(window, Theme.Animation.WindowFade, { GroupTransparency = 0 })
            tween(wsc,   Theme.Animation.WindowFade, { Scale = 1 })
        else
            window.GroupTransparency = 0
            if _us_cache[window] then _us_cache[window].Scale = 1 end
        end
        -- v0.0.95: force the cursor UNLOCKED + visible while the menu is up so
        -- the user can click Koffee widgets without having to open the Roblox
        -- menu (Esc) first. Restore whatever the game/3rd-Person had set on close.
        _preMenuMouseBehavior = UserInputService.MouseBehavior
        _preMenuMouseIcon     = UserInputService.MouseIconEnabled
        UserInputService.MouseBehavior   = Enum.MouseBehavior.Default
        UserInputService.MouseIconEnabled = true
        -- LockFirstPerson makes the ENGINE hold the cursor centred, under the
        -- re-assert. Classic frees it without zooming out, because the camera keeps
        -- its current distance and forced-first-person games pin that at min zoom.
        _preMenuCamMode = LocalPlayer.CameraMode
        if _preMenuCamMode == Enum.CameraMode.LockFirstPerson then
            pcall(function() LocalPlayer.CameraMode = Enum.CameraMode.Classic end)
        end
        holdMouseFree(true)
    else
        -- v0.0.22: popups live in a SEPARATE ScreenGui, so the window's fade
        -- doesn't touch them. Dismiss any open color picker + dropdowns on close
        -- so they don't linger over the game after the menu is hidden.
        closeColorPicker()
        for _, closer in pairs(openDropdowns) do closer(true) end
        for _, closer in pairs(openSettingsPopups) do closer() end
        if Koffee.Anim.spot("AnimWindow") then
            tween(window, Theme.Animation.WindowFade, { GroupTransparency = 1 })
            -- v0.0.98: sink slightly as it goes, with the fade.
            if _us_cache[window] then
                tween(_us_cache[window], Theme.Animation.WindowFade, { Scale = 0.96 })
            end
            task.delay(Koffee.Anim.wait(0.2), function()
                if not windowOpen then window.Visible = false end
            end)
        else
            window.GroupTransparency = 1
            window.Visible = false
            if _us_cache[window] then _us_cache[window].Scale = 0.96 end
        end
        -- restore prior mouse state (3rd Person etc. re-locks on its own next
        -- frame if it's still enabled; otherwise game gets whatever it had)
        holdMouseFree(false)
        if _preMenuCamMode then
            pcall(function() LocalPlayer.CameraMode = _preMenuCamMode end)
            _preMenuCamMode = nil
        end
        if _preMenuMouseBehavior then
            UserInputService.MouseBehavior = _preMenuMouseBehavior
        end
        if _preMenuMouseIcon ~= nil then
            UserInputService.MouseIconEnabled = _preMenuMouseIcon
        end
    end
    setBackgroundActive(open)
end
-- v0.25.0: Design Mode closes the window so the whole screen is the canvas.
Shared.setWindowOpen = setWindowOpen

-- initial state
window.GroupTransparency = 0
window.Visible = true
setBackgroundActive(true)

-- v0.0.36: does this input fire a bind? Binds are EnumItems: a KeyCode
-- (keyboard) OR a UserInputType (mouse/other button).
local function bindMatches(input, bind)
    -- v0.0.94 combo bind: { mod = KeyCode, key = KeyCode }: fires only when
    -- the target key is pressed AND the modifier is currently held.
    if type(bind) == "table" and bind.mod and bind.key then
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return false end
        if input.KeyCode ~= bind.key then return false end
        return UserInputService:IsKeyDown(bind.mod)
    end
    if typeof(bind) ~= "EnumItem" then return false end
    if bind.EnumType == Enum.KeyCode then
        return input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == bind
    elseif bind.EnumType == Enum.UserInputType then
        return input.UserInputType == bind
    end
    return false
end

UserInputService.InputBegan:Connect(function(input, processed)
    local it = input.UserInputType

    -- pending rebind captures ANY key/button (bypasses processed so users can
    -- rebind even with a textbox focused). v0.0.36: ESC CLEARS the bind; mouse
    -- buttons (and whatever the runtime surfaces, e.g. XButton1/2) are accepted.
    if pendingRebind then
        local pill = pendingRebind.pill
        if it == Enum.UserInputType.Keyboard and input.KeyCode == Enum.KeyCode.Escape then
            Keybinds[pendingRebind.moduleId] = nil
            pill.Text = "No Keybind"
            tween(pill, Theme.Animation.Fast, { TextColor3 = Theme.Palette.TextMuted })
            pendingRebind = nil
            return
        end
        -- v0.27.0: bind mouse buttons even when the click lands on the koffee UI.
        -- Rebind is armed ("...") so the next press is intentional, and the arming
        -- click's own edge already fired. (gpe-gating forced a game-world click.)
        -- v0.0.94: pressing JUST a modifier alone (Shift/Ctrl/Alt without another key)
        -- doesn't complete the rebind: user needs to press the actual key while
        -- holding the modifier. Otherwise the modifier itself gets bound as the key.
        if it == Enum.UserInputType.Keyboard then
            local kc = input.KeyCode
            if kc == Enum.KeyCode.LeftShift  or kc == Enum.KeyCode.RightShift
            or kc == Enum.KeyCode.LeftControl or kc == Enum.KeyCode.RightControl
            or kc == Enum.KeyCode.LeftAlt    or kc == Enum.KeyCode.RightAlt then
                return   -- wait for a real key
            end
        end
        local bind
        if it == Enum.UserInputType.Keyboard and input.KeyCode ~= Enum.KeyCode.Unknown then
            -- v0.0.94: capture combo if any modifier is currently held.
            local heldMod
            if     UserInputService:IsKeyDown(Enum.KeyCode.LeftShift)   then heldMod = Enum.KeyCode.LeftShift
            elseif UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then heldMod = Enum.KeyCode.LeftControl
            elseif UserInputService:IsKeyDown(Enum.KeyCode.LeftAlt)     then heldMod = Enum.KeyCode.LeftAlt
            elseif UserInputService:IsKeyDown(Enum.KeyCode.RightShift)  then heldMod = Enum.KeyCode.RightShift
            elseif UserInputService:IsKeyDown(Enum.KeyCode.RightControl)then heldMod = Enum.KeyCode.RightControl
            elseif UserInputService:IsKeyDown(Enum.KeyCode.RightAlt)    then heldMod = Enum.KeyCode.RightAlt
            end
            if heldMod then bind = { mod = heldMod, key = input.KeyCode }
            else bind = input.KeyCode end
        elseif it ~= Enum.UserInputType.Focus and it ~= Enum.UserInputType.MouseMovement
           and it ~= Enum.UserInputType.MouseWheel and it ~= Enum.UserInputType.None
           and it ~= Enum.UserInputType.TextInput and it ~= Enum.UserInputType.InputMethod then
            bind = it
        end
        if bind then completeRebind(bind) end
        return
    end

    if processed then return end

    -- menu toggle (keyboard only)
    if it == Enum.UserInputType.Keyboard
    and (input.KeyCode == Enum.KeyCode.Delete or input.KeyCode == Enum.KeyCode.RightShift) then
        setWindowOpen(not windowOpen)
        return
    end

    -- module bindings (KeyCode or UserInputType)
    for id, key in pairs(Keybinds) do
        if bindMatches(input, key) then
            toggleModule(id)
            return
        end
    end
end)

-- v0.0.37: MODULE-keybind virtual XButton driver (mirror of the combat one, for
-- module keybind pills). Roblox can't fire mouse 4/5, so the helper drives rebind
-- capture + module toggles for keybinds set to a virtual XButton.
;(function()
    local pXB1, pXB2 = false, false
    RunService.Heartbeat:Connect(function()
        if Koffee.dead() then return end
        local xb1, xb2 = Helper.XB1, Helper.XB2
        local e1, e2 = (xb1 and not pXB1), (xb2 and not pXB2)
        if pendingRebind then
            local k = (e2 and "XButton2") or (e1 and "XButton1") or nil
            if k then
                Keybinds[pendingRebind.moduleId] = k
                pendingRebind.pill.Text = keyLabel(k)
                tween(pendingRebind.pill, Theme.Animation.Fast, { TextColor3 = Theme.Palette.TextMuted })
                pendingRebind = nil
            end
        elseif e1 or e2 then
            for id, key in pairs(Keybinds) do
                if (key == "XButton2" and e2) or (key == "XButton1" and e1) then
                    toggleModule(id)
                end
            end
        end
        pXB1, pXB2 = xb1, xb2
    end)
end)()

-- v0.0.37: poll the Koffee Helper for OS-level input (XButton1/2). It serves live
-- button state over localhost; we cache it in `Helper` for the virtual-bind drivers.
-- Degrades silently on a slow backoff when the helper isn't running.
;(function()
    local HttpService = game:GetService("HttpService")
    local reqFn = (syn and syn.request) or (http and http.request) or http_request or request
    if reqFn then
        task.spawn(function()
            while true do
                -- v0.22.0: was immortal. Unload kept polling the helper forever and
                -- each re-exec added another poller (3 runs = ~90 req/s at :7912).
                if Koffee.dead() then
                    Helper.Connected, Helper.XB1, Helper.XB2 = false, false, false
                    break
                end
                local ok, res = pcall(reqFn, {
                    Url = Helper.Url(Helper.PortInput, "/"), Method = "GET",
                    Headers = Helper.Headers(),
                })
                local body = ok and res and res.Body
                local data
                if body then
                    local dok, decoded = pcall(function() return HttpService:JSONDecode(body) end)
                    if dok then data = decoded end
                end
                if type(data) == "table" then
                    if not Helper.Connected then
                        Helper.Connected = true
                        print("[koffee] helper connected: XButton1/2 available")
                    end
                    Helper.XB1 = data.xb1 and true or false
                    Helper.XB2 = data.xb2 and true or false
                    task.wait(0.03)
                else
                    if Helper.Connected then print("[koffee] helper disconnected") end
                    Helper.Connected, Helper.XB1, Helper.XB2 = false, false, false
                    task.wait(1)
                end
            end
        end)
    end
end)()

-- v0.0.34: auto-load this game's saved config (if one is pinned). Deferred +
-- pcall'd so a bad/locked config never blocks the UI from coming up.
task.spawn(function()
    local auto = Koffee.Config.getAuto()
    if not auto then return end
    task.wait(0.25)
    pcall(function() Koffee.Config.load(auto) end)
end)
end)()

return Koffee
